Consider a $d$-dimensional \textit{target} SDE defined on a filtered probability space $\big(\Omega, \mathcal{F}, \mathbb{P}, \{\mathcal{F}_t\}_{0\le t\le T}\big)$:\begin{equation}\label{eq: target_SDE}
	\mathrm{d}\mathbf{X}(t) = \mu(t, \mathbf{X}(t))\mathrm{d} t + \sigma(t, \mathbf{X}(t))\mathrm{d}\mathbf{W}(t),\ t \in [0, T],
\end{equation}
where $\mu: [0, T] \times \mathbb{R}^d \to \mathbb{R}^d$ is the drift coefficient, $\sigma: [0, T] \times \mathbb{R}^d \to \mathbb{R}^{d\times m}$ is the diffusion coefficient, and $\mathbf{W}$ is a standard $m$-dimensional Brownian motion.

\begin{equation}\label{eq: target_SDE}
	\mathrm{d}\mathbf{X}(t) = \mu(t, \mathbf{X}(t))\mathrm{d} t + \sigma(t, \mathbf{X}(t))\mathrm{d}\mathbf{W}(t),\ t \in [0, T],
\end{equation}

The dataset available to us, therefore,  consists of $H > 1$ sample paths of $\{\mathbf{X}(t): t \in [0, T]\}$ observed at grid points in $\mathcal{T}$ (i.e. time series), denoted by
\begin{align}\label{eq: obs_data}
	\left\{\mathbf{x}^{(i)}(t_0), \mathbf{x}^{(i)}(t_1), \cdots, \mathbf{x}^{(i)}(t_{N_T}),\quad i=1, ..., H\right\}.
\end{align}

\begin{align}\label{eq: obs_data}
	\left\{\mathbf{x}^{(i)}(t_0), \mathbf{x}^{(i)}(t_1), \cdots, \mathbf{x}^{(i)}(t_{N_T}),\quad i=1, ..., H\right\}.
\end{align}

\begin{align}\label{eq: forward_SDE_DDPM}
    \mathrm{d}\mathbf{Y}(\tau) = -f(\tau)\mathbf{Y}(\tau)\mathrm{d}\tau + g(\tau) \mathrm{d}\mathbf{B}(\tau),\ \mathbf{Y}(0)\sim q_0(\cdot | \mathbf{c}),\ \tau\in [0, T_g],
\end{align}

The noising process \eqref{eq: forward_SDE_DDPM} is called the \textit{forward process} which admits an analytical solution
\begin{align*}
    \mathbf{Y}(\tau) &= e^{-\int_0^\tau f(v)\mathrm{d} v}\mathbf{Y}(0) + \int_{0}^\tau e^{-\int_u^\tau f(v)\mathrm{d} v}g(u) \mathrm{d} \mathbf{B}(u).
\end{align*}

\begin{align*}
    \mathbf{Y}(\tau) &= e^{-\int_0^\tau f(v)\mathrm{d} v}\mathbf{Y}(0) + \int_{0}^\tau e^{-\int_u^\tau f(v)\mathrm{d} v}g(u) \mathrm{d} \mathbf{B}(u).
\end{align*}

Under mild assumptions \citep{Anderson1982, cattiaux2023time, haussmann1986time}, $\tilde{\mathbf{Y}}$ satisfies the reverse SDE starting from $\tilde{\mathbf{Y}}(0)\sim q_{T_g}(\cdot | \mathbf{c})$:
\begin{align}\label{eq: reverse_SDE_DDPM}
    \mathrm{d}\tilde{\mathbf{Y}}(\tau) = [f(T_g - \tau)\tilde{\mathbf{Y}}(\tau) + g^2(T_g - \tau) \nabla\log q_{T_g - \tau}(\tilde {\mathbf{Y}}(\tau) | \mathbf{c})]\mathrm{d}\tau + g(T_g - \tau) \mathrm{d}\tilde{\mathbf{B}}(\tau),
\end{align}
where $\nabla\log q_{\tau}(\cdot | \mathbf{c})$ is called the (conditional) score function and is unknown.

\begin{align}\label{eq: reverse_SDE_DDPM}
    \mathrm{d}\tilde{\mathbf{Y}}(\tau) = [f(T_g - \tau)\tilde{\mathbf{Y}}(\tau) + g^2(T_g - \tau) \nabla\log q_{T_g - \tau}(\tilde {\mathbf{Y}}(\tau) | \mathbf{c})]\mathrm{d}\tau + g(T_g - \tau) \mathrm{d}\tilde{\mathbf{B}}(\tau),
\end{align}

\begin{align}\label{eq: denosing_score_matching}
    \min_{\theta}\mathbb{E}_{\mathbf{c}\sim\mathbf{C}}\mathbb{E}_{\tau\sim \text{Unif}[0, T_g]} \mathbb{E}_{\mathbf{Y}(0)} \mathbb{E}_{\mathbf{Y}(\tau)|(\mathbf{Y}(0), \mathbf{c})}\bigg[\lambda(\tau)\big\| s_\theta(\tau, \mathbf{Y}(\tau), \mathbf{c}) - \nabla\log q_{\tau|0}(\mathbf{Y}(\tau) | \mathbf{Y}(0), \mathbf{c})\big\|^2\bigg],
\end{align}

For $k=0,1,\cdots,K-1$, set
\begin{align}\label{eq: reverse_SDE_DDPM_simulation}
    \tilde{\mathbf{Z}}(\tau_{k + 1}) = \tilde{\mathbf{Z}}(\tau_{k}) + [\tilde f(\tau_k)\tilde{\mathbf{Z}}(\tau_k) + \tilde g^2(\tau_k) s_\theta(T_g - \tau_k, \tilde{\mathbf{Z}}(\tau_{k})), \mathbf{c})]\Delta\tau + \tilde g(\tau_k)\sqrt{\Delta\tau} \cdot \zeta_k,
\end{align}
where $\tilde f(\tau) = f(T_g - \tau), \tilde g(\tau) = g(T_g - \tau)$, and $\zeta_k$'s are i.i.d. standard Gaussian random vectors.

\begin{align}\label{eq: reverse_SDE_DDPM_simulation}
    \tilde{\mathbf{Z}}(\tau_{k + 1}) = \tilde{\mathbf{Z}}(\tau_{k}) + [\tilde f(\tau_k)\tilde{\mathbf{Z}}(\tau_k) + \tilde g^2(\tau_k) s_\theta(T_g - \tau_k, \tilde{\mathbf{Z}}(\tau_{k})), \mathbf{c})]\Delta\tau + \tilde g(\tau_k)\sqrt{\Delta\tau} \cdot \zeta_k,
\end{align}

For each $t_n$, we set condition $\mathbf{c}_n = (t_n, \mathbf{x}(t_n))$ sampled from $\mathbf{C}_n = (t_n, \mathbf{X}(t_n))$ and train a conditional diffusion model $G(t_n, \mathbf{x}; \theta_n)$ where $\mathbf{x}(t_n)=\mathbf{x}$, such that $G(t_n, \mathbf{x}; \theta_n)$ consists of a score network $s_{\theta_n}$ trained via \eqref{eq: denosing_score_matching} and generates new samples $\tilde{\mathbf{Z}}_n(\tau_K)$ distributed as $\Delta\mathbf{X}(t_n; \mathbf{x})$ by running \eqref{eq: reverse_SDE_DDPM_simulation}, i.e.,
\begin{align}\label{eq: objective_AR_gen}
	\tilde{\mathbf{Z}}_n(\tau_K)\overset{d}{\approx}  \Delta \mathbf{X}(t_n; \mathbf{x}) := \mathbf{X}(t_n + \Delta t) - \mathbf{x} =  \int_{t_n}^{t_n + \Delta t}\mu(t, \mathbf{X}(t))\mathrm{d} t + \int_{t_n}^{t_n + \Delta t}\sigma(t, \mathbf{X}(t))\mathrm{d}\mathbf{W}(t).
\end{align}

\begin{align}\label{eq: objective_AR_gen}
	\tilde{\mathbf{Z}}_n(\tau_K)\overset{d}{\approx}  \Delta \mathbf{X}(t_n; \mathbf{x}) := \mathbf{X}(t_n + \Delta t) - \mathbf{x} =  \int_{t_n}^{t_n + \Delta t}\mu(t, \mathbf{X}(t))\mathrm{d} t + \int_{t_n}^{t_n + \Delta t}\sigma(t, \mathbf{X}(t))\mathrm{d}\mathbf{W}(t).
\end{align}

\begin{align}
	\hat{\mathbf{X}}(t_{n+1}) = \hat{\mathbf{x}}(t_{n }) + \tilde{\mathbf{Z}}_n(\tau_K),\quad  \text{for}\ n = 0, ..., N_T-1. \label{eq: AR_generation}
\end{align}

\small
\caption{Training process of the SDE generative model
$\{G(t_n, \cdot; \theta_n): n=0, \cdots, N_T - 1\}$}
\begin{algorithmic}\label{alg: training_process}
    \REQUIRE Training data $\{(\mathbf{x}^{(i)}(t_n), \Delta\mathbf{x}^{(i)}(t_n; \mathbf{x}^{(i)}(t_n))): i=1,\cdots, H, n=0, \cdots, N_T - 1\}$, score networks $\{s_{\theta_n}\}_{n=0}^{N_T - 1}$, batch size $m\le H$, learning rate function $\alpha(\cdot)$, noise schedulers $f(\tau)$ and $g(\tau)$, diffusion horizon $T_g$, number of diffusion steps $K$, diffusion time step $\Delta\tau = T_g/K$
    \FOR{episode $j = 1,..., J$}
    \FOR{SDE slot $t_n= 0, \Delta t, 2\Delta t, ..., (N_T - 1)\Delta t$}
    \STATE 1. Randomly sample a batch of data at $t_n$:
    \vspace{-2mm}
        $$\big\{(\mathbf{c}^{(i_l)}, \mathbf{y}^{(i_l)}(0)) = ((t_n, \mathbf{x}^{(i_l)}(t_n)), \Delta\mathbf{x}^{(i_l)}(t_n; \mathbf{x}^{(i_l)}(t_n))): l=1,\cdots, m\big\}$$
    \vspace{-7mm}
    \STATE 2. Randomly sample a diffusion step $k\sim \text{Unif}[1, K]$ and set $\tau_k = k\Delta\tau$
    \STATE 3. Generate noised samples $\{\mathbf{y}^{(i_l)}(\tau_k): l=1,\cdots, m\}$, where
    \vspace{-3mm}
    \[\mathbf{y}^{(i_l)}(\tau_k) = e^{-\int_0^{\tau_k} f(v)\mathrm{d} v}\mathbf{y}^{i_l}(0) + \bigg(\int_{0}^{\tau_k} e^{-\int_u^{\tau_k} 2f(v)\mathrm{d} v}g^2(u) \mathrm{d} u\bigg)^{1/2}\zeta_l,\ \zeta_l\sim\mathcal{N}(0, I_d)
    \]
    \vspace{-5mm}
    \STATE 4. Compute the denosing score matching loss $L(\theta_n)$\footnotemark:
    \vspace{-2mm}
    \begin{align*}
    \frac{1}{m}\sum_{l=1}^m \int_{0}^{\tau_k} e^{-\int_u^{\tau_k} 2f(v)\mathrm{d} v}g^2(u) \mathrm{d} u\cdot\big\| s_{\theta_n}(\tau_k, \mathbf{y}^{(i_l)}(\tau_k), \mathbf{c}^{(i_l)}) - \nabla\log q_{\tau_k|0}(\mathbf{y}^{(i_l)}(\tau_k) | \mathbf{y}^{(i_l)}(0), \mathbf{c}^{(i_l)})\big\|^2
    \end{align*}
    \vspace{-4mm}
    \STATE 5. Update $\theta_n \leftarrow \theta_n - \alpha(j)\nabla_{\theta_n} L(\theta_n)$
    \ENDFOR
    \ENDFOR
    \RETURN score network $s_{\theta_n}$ of $G(t_n, \cdot; \theta_n)$ for $n=0, \cdots, N_T-1$
\end{algorithmic}

\begin{align*}
    \frac{1}{m}\sum_{l=1}^m \int_{0}^{\tau_k} e^{-\int_u^{\tau_k} 2f(v)\mathrm{d} v}g^2(u) \mathrm{d} u\cdot\big\| s_{\theta_n}(\tau_k, \mathbf{y}^{(i_l)}(\tau_k), \mathbf{c}^{(i_l)}) - \nabla\log q_{\tau_k|0}(\mathbf{y}^{(i_l)}(\tau_k) | \mathbf{y}^{(i_l)}(0), \mathbf{c}^{(i_l)})\big\|^2
    \end{align*}

\small
\caption{Generation of synthetic SDE paths}
\begin{algorithmic}\label{alg: generation_process}
    \REQUIRE network $\{s_{\theta_n}\}_{n=0}^{N_T - 1}$, initial position $\hat{\mathbf{x}}(t_0)=\mathbf{x}(0)$, noise schedulers $f(\tau)$ and $g(\tau)$, diffusion horizon $T_g$, number of diffusion steps $K$, diffusion time step $\Delta\tau = T_g/K$
    \FOR{SDE slot $t_n= 0, \Delta t, 2\Delta t, ..., (N_T - 1)\Delta t$}
    \STATE 1. Set the condition $\mathbf{c}_n = (t_n, \hat{\mathbf{x}}(t_n))$
    \STATE 2. Simulate $\tilde{\mathbf{y}}(\tau_0)\sim\mathcal{N}(0, I_d)$
    \STATE 3. Simulate the reverse process of the conditional diffusion model:
    \FOR{diffusion step $\tau_k = 0, \Delta\tau, 2\Delta\tau, \cdots, K\Delta\tau$}
    \vspace{-5mm}
        \STATE
        \[\tilde{\mathbf{y}}(\tau_{k + 1}) = \tilde{\mathbf{y}}(\tau_{k}) + [ f(T_g -\tau_{k})\tilde{\mathbf{y}}(\tau_{k}) +  g^2(T_g -\tau_{k}) s_{\theta_n}(T_g - \tau_k, \tilde{\mathbf{y}}(\tau_{k}), \mathbf{c}_n)]\Delta\tau + g(T_g - \tau_k) \sqrt{\Delta\tau}\zeta_k
        \]

        where $\zeta_k\sim\mathcal{N}(0, I_d)$
    \ENDFOR
    \STATE 4. Set and store the next state $\hat{\mathbf{x}}(t_{n + 1}) = \hat{\mathbf{x}}(t_n) + \tilde{\mathbf{y}}(\tau_{K})$
    \ENDFOR

    \RETURN generated path $(\hat{\mathbf{x}}(t_0), \hat{\mathbf{x}}(t_1), \cdots, \hat{\mathbf{x}}(t_{N_T}))$
\end{algorithmic}

