\label{assumption: SDE_solution_supp_abs}
    (a) The coefficients $\mu$ and $\sigma$ of the target SDE \eqref{eq: target_SDE} satisfy the global Lipschitz and linear growth conditions:
    \begin{align*}
        ||\mu(t, \mathbf{x}) - \mu(t, \mathbf{x}')||_2 + ||\sigma(t, \mathbf{x}) - \sigma(t, \mathbf{x}')||_2 &\le C_L||\mathbf{x} - \mathbf{x}'||_2,\\
        ||\mu(t, \mathbf{x})||_2 + ||\sigma(t, \mathbf{x})||_2 &\le C_L(1 + ||\mathbf{x}||_2),
    \end{align*}
    for every $t\in[0, T], \mathbf{x}\in\mathbb{R}^d, \mathbf{x}'\in\mathbb{R}^d$, where $C_L$ is a positive constant independent of $(t, \mathbf{x},\mathbf{x}')$.

   (b) For any $0 \le s \le t \le T$,  the conditional distribution of $\mathbf{X}(t)$ given $\mathbf{X}(s) = \mathbf{x}(s)$ is absolutely continuous w.r.t. the Lebesgue measure, and it admits a probability density function that is positive almost everywhere on $\mathbb{R}^d$.

\begin{align*}
        ||\mu(t, \mathbf{x}) - \mu(t, \mathbf{x}')||_2 + ||\sigma(t, \mathbf{x}) - \sigma(t, \mathbf{x}')||_2 &\le C_L||\mathbf{x} - \mathbf{x}'||_2,\\
        ||\mu(t, \mathbf{x})||_2 + ||\sigma(t, \mathbf{x})||_2 &\le C_L(1 + ||\mathbf{x}||_2),
    \end{align*}

\begin{align} \label{eq: target_SDE_moment_bound}
    \mathbb{E}\|\mathbf{X}(t_{n + 1}) - \mathbf{X}(t_n)\|^2 &\le M_2(t_n; T) \cdot e^{\Delta tC_M}\Delta t
\end{align}

\begin{align*}
   M_2(t_n; T)&:= D_1 \cdot (T - t_n + 1)(1 + \mathbb{E}\|\mathbf{X}(t_n)\|^2) \nonumber \\
   & \le D_2\cdot (T - t_n + 1)(1 + \mathbb{E}\|\mathbf{X}(0)\|^2)e^{t_{n}C_M },
\end{align*}

\label{prop: path_KL_decomposition}
     Suppose that Assumption \ref{assumption: SDE_solution_supp_abs} holds. Then,
     \begin{enumerate}
         \item both $P_{\Delta\mathbf{X}(t_n; \mathbf{x}(t_n))}$ and $\hat P_{\Delta\hat{\mathbf{X}}(t_n; \mathbf{X}(t_n))}$ are equivalent to the Lebesgue measure and admit density functions that are positive almost everywhere on $\mathbb{R}^d$.

        \item  Both $P_{1:N_T|0}$ and $\hat P_{1:N_T|0}$ are equivalent to the Lebesgue measure and admit density functions that are positive almost everywhere on $\mathbb{R}^{d\times N_T}$. Moreover, we have
        \begin{align}\label{eq: path_KL_decomposition}
            \text{KL}\big(P_{1:N_T|0} ||\hat P_{1:N_T|0}\big) = \sum_{n=0}^{N_T - 1}\mathbb{E}_{\mathbf{X}(t_n)\sim P_{n|0}}\bigg[\text{KL}\big(P_{\Delta\mathbf{X}(t_n; \mathbf{X}(t_n))} \big|\big| \hat P_{\Delta\hat{\mathbf{X}}(t_n; \mathbf{X}(t_n))}\big)\bigg],
        \end{align}
        where $P_{n|0}$ is the marginal distribution of the SDE solution $\mathbf{X}(t_n)$ conditional on $\mathbf{X}(t_0) \equiv \mathbf{x}(t_0)$. 
     \end{enumerate}

\begin{align}\label{eq: path_KL_decomposition}
            \text{KL}\big(P_{1:N_T|0} ||\hat P_{1:N_T|0}\big) = \sum_{n=0}^{N_T - 1}\mathbb{E}_{\mathbf{X}(t_n)\sim P_{n|0}}\bigg[\text{KL}\big(P_{\Delta\mathbf{X}(t_n; \mathbf{X}(t_n))} \big|\big| \hat P_{\Delta\hat{\mathbf{X}}(t_n; \mathbf{X}(t_n))}\big)\bigg],
        \end{align}

\label{prop: condition_diffusion_KL_bound}
Suppose the following conditions hold:
\begin{enumerate}
    \item for any given condition $\mathbf{c}$, the target conditional distribution admits a twice continuously differentiable density function $p_{\text{target}}(\cdot | \mathbf{c})$, which is positive almost everywhere on $\mathbb{R}^{d_{\text{target}}}$ and the corresponding score function $\nabla\log p_{\text{target}}(\cdot | \mathbf{c})$ is $L(\mathbf{c})$-Lipschitz continuous with
    \begin{align}\label{eq: convergence_lipschitz}
        \mathbb{E}_{\mathbf{c}\sim\mathbf{C}}[L(\mathbf{c})] = L_1 < \infty.
    \end{align}

    \item The target distribution has a finite second moment, i.e.
    \begin{align}\label{eq: convergence_finite_moment}
        \mathbb{E}_{\mathbf{c}\sim\mathbf{C}}\big[\mathbb{E}_{\mathbf{Y}(0)\sim p_{\text{target}}(\cdot | \mathbf{c})}||\mathbf{Y}(0)||^2\big] < M_2
    \end{align}
    for some positive constant $M_2$.

    \item There exists a small constant $\varepsilon_{\text{score}}>0$ such that
    \begin{align}\label{eq: convergence_score_matching}
        \frac{1}{K}\sum_{k=1}^K\mathbb{E}_{\mathbf{c}\sim\mathbf{C}}\bigg[\mathbb{E}_{\mathbf{Y}(\tau_k)\sim q_{\tau_k}(\cdot | \mathbf{c})}\big[||\nabla\log q_{\tau_k}(\mathbf{Y}(\tau_k) | \mathbf{c}) - s_\theta(\tau_k, \mathbf{Y}(\tau_k), \mathbf{c})||^2\big]\bigg] \le \varepsilon_{\text{score}}^2.
    \end{align}
\end{enumerate}

Then, we have
\begin{align}
    &\mathbb{E}_{\mathbf{c}\sim\mathbf{C}}\left[\text{KL}\big(p_{\text{target}}(\cdot | \mathbf{c}) || \tilde p^\theta_{\tau_K}(\cdot | \mathbf{c})\big)\right]\nonumber\\
    &\lesssim \underbrace{e^{-\frac{a}{2}T_g^2 - bT_g}\big[M_2 + de^{-\frac{a}{2}T_g^2 - bT_g}\big]}_{{\text(i)}} + \underbrace{(T_g + 1)^3 \varepsilon_{\text{score}}^2}_{\text{(ii)}} + \underbrace{\Delta\tau(M_2 + d)(T_g + 1)^5}_{\text{(iii)}} \nonumber\\
    &\qquad + \underbrace{M_2\Delta\tau (T_g + 1)^2 + d\Delta\tau \big[L_1 + (T_g + 1)^4 \big]}_{\text{(iv)}} + \underbrace{d(\Delta\tau)^2(L_1 + T_g + 1)}_{\text{(v)}}.\label{eq: condition_diffusion_KL_bound} 
\end{align}

\begin{align}\label{eq: convergence_lipschitz}
        \mathbb{E}_{\mathbf{c}\sim\mathbf{C}}[L(\mathbf{c})] = L_1 < \infty.
    \end{align}

\begin{align}\label{eq: convergence_finite_moment}
        \mathbb{E}_{\mathbf{c}\sim\mathbf{C}}\big[\mathbb{E}_{\mathbf{Y}(0)\sim p_{\text{target}}(\cdot | \mathbf{c})}||\mathbf{Y}(0)||^2\big] < M_2
    \end{align}

