Given a fixed condition $\mathbf{c}$, we first state Lemma \ref{lemma: KL_bound_decomposition} below, which decomposes $\text{KL}\big(p_{\text{target}}(\cdot | \mathbf{c}) || \tilde p^\theta_{\tau_K}(\cdot | \mathbf{c})\big)$ and identifies various sources of approximation errors.

\begin{lemma}\label{lemma: KL_bound_decomposition}
For a given condition $\mathbf{c}$, denote by $\tilde p^\theta_{\tau_K}(\cdot | \mathbf{c})$ the marginal density of the generated $\tilde{\mathbf{Z}}(\tau_K)$ of the reverse process \eqref{eq: reverse_SDE_DDPM_simulation}. Under the conditions of Proposition \ref{prop: condition_diffusion_KL_bound}, we have
\begin{align}
        &\text{KL}\big(p_{\text{target}}(\cdot | \mathbf{c}) || \tilde p^\theta_{\tau_K}(\cdot | \mathbf{c})\big) \nonumber\\
        &\lesssim \text{KL}\big(q_{T_g}(\cdot | \mathbf{c}) || \mathcal{N}(0, I_d)\big) +  \sum_{k=1}^{K} \int_{\tau_{k-1}}^{\tau_k}\mathbb{E}_{\mathbf{Y}(\tau)\sim q_\tau(\cdot | \mathbf{c}), \mathbf{Y}(\tau_k)\sim q_{\tau_k|\tau}(\cdot |\mathbf{Y}(\tau), \mathbf{c})}\big[||f(\tau)\mathbf{Y}(\tau) - f(\tau_k)\mathbf{Y}(\tau_k)||^2\big]\mathrm{d}\tau \nonumber\\
        &\qquad + \sum_{k=1}^{K} \int_{\tau_{k-1}}^{\tau_k}\mathbb{E}_{\mathbf{Y}(\tau)\sim q_\tau(\cdot | \mathbf{c}), \mathbf{Y}(\tau_k)\sim q_{\tau_k | \tau}(\cdot | \mathbf{Y}(\tau), \mathbf{c})}\big[||g^2(\tau)\nabla\log q_\tau(\mathbf{Y}(\tau) | \mathbf{c}) - g^2(\tau_k)\nabla\log q_{\tau_k}(\mathbf{Y}(\tau_k) | \mathbf{c})||^2\big]\mathrm{d}\tau\nonumber\\
        &\qquad +  \sum_{k=1}^{K}\int_{\tau_{k - 1}}^{\tau_{k}}[g^2(\tau_k) - g^2(\tau)]^2\mathbb{E}_{\mathbf{Y}(\tau)\sim q_{\tau}(\cdot | \mathbf{c})} \big[\big\|\nabla\log q_\tau(\mathbf{Y}(\tau) | \mathbf{c})\big\|^2\big] \mathrm{d}\tau \nonumber \\
        &\qquad + \Delta \tau\sum_{k=1}^{K}\mathbb{E}_{\mathbf{Y}\sim q_{\tau_k}(\cdot | \mathbf{c})}\big[||g^2(\tau_k)\nabla\log q_{\tau_k}(\mathbf{Y}(\tau_k) | \mathbf{c}) - g^2(\tau_k)s_\theta(\tau_k, \mathbf{Y}(\tau_k), \mathbf{c})||^2\big].\label{eq: KL_bound_decomposition}
\end{align}
\end{lemma}

The proof of Lemma \ref{lemma: KL_bound_decomposition} can be found in Appendix \ref{sec: error_identification}. We next discuss how to bound each term on the right-hand-side of \eqref{eq: KL_bound_decomposition}.



The first term of \eqref{eq: KL_bound_decomposition} is the initialization error arising from the use of the Gaussian noise, instead of the terminal state of the forward process, as the initialization of the generation process \eqref{eq: reverse_SDE_DDPM_simulation}. We bound this initialization error in Lemma \ref{lemma: initial_dist_error_bound}, leveraging on the exponential convergence property of the forward OU process \eqref{eq: forward_SDE_DDPM}. The proof of Lemma~\ref{lemma: initial_dist_error_bound} is given in Appendix \ref{sec: Gaussian_initialization_error}.


\begin{lemma}\label{lemma: initial_dist_error_bound}
For the terminal marginal density $q_{T_g}(\cdot | \mathbf{c})$ induced by the forward process defined in \eqref{eq: forward_SDE_DDPM}, if the moment condition \eqref{eq: convergence_finite_moment} is satisfied, then we have:
    \begin{align*}
        \mathbb{E}_{\mathbf{c}\sim\mathbf{C}}\bigg[\text{KL}\big(q_{T_g}(\cdot | \mathbf{c}) || \mathcal{N}(0, I_d)\big)\bigg]\lesssim e^{-\frac{a}{2}T_g^2 - bT_g}\big[M_2 + de^{-\frac{a}{2}T_g^2 - bT_g}\big].
    \end{align*}
\end{lemma}

Next, we bound the second term of \eqref{eq: KL_bound_decomposition}, which accounts for the state discretization error of using $f(\tau_k)\mathbf{Y}(\tau_k)$ to approximate $f(\tau)\mathbf{Y}(\tau)$ for $\tau\in[\tau_{k - 1}, \tau_k]$. Lemma \ref{lemma: state_discrete_error_bound} shows that this error can be controlled under the finite moment condition \eqref{eq: convergence_finite_moment}. The proof, deferred to Appendix \ref{sec: state_discrretization_error}, is based on applying It\^{o}'s formula to $f(\tau)\mathbf{Y}(\tau)$.



\begin{lemma}\label{lemma: state_discrete_error_bound}
    For the forward process $\mathbf{Y}$ in \eqref{eq: forward_SDE_DDPM}, if the moment condition \eqref{eq: convergence_finite_moment} is satisfied, then we have:
    \begin{align*}
    &\mathbb{E}_{\mathbf{c}\sim\mathbf{C}}\bigg[\sum_{k=1}^{K} \int_{\tau_{k -1}}^{\tau_k}\mathbb{E}_{\mathbf{Y}(\tau)\sim q_\tau(\cdot | \mathbf{c}), \mathbf{Y}(\tau_k)\sim q_{\tau_k | \tau}(\cdot | \mathbf{Y}(\tau), \mathbf{c})}\big[||f(\tau)\mathbf{Y}(\tau) - f(\tau_k)\mathbf{Y}(\tau_k)||^2\big]\mathrm{d}\tau\bigg] \\
    &\lesssim \Delta\tau(M_2 + d)(T_g + 1)^5.
\end{align*}
\end{lemma}


The third error term in \eqref{eq: KL_bound_decomposition} represents the time and space discretization error for approximating the score function $g^2(\tau)\nabla\log q_{\tau}(\mathbf{Y}(\tau)|\mathbf{c})$ by $g^2(\tau_k)\nabla\log q_{\tau_k}(\mathbf{Y}(\tau_k)| \mathbf{c})$ when $\tau\in[\tau_{k - 1}, \tau_k]$. We bound this error in Lemma \ref{lemma: score_discretization_error_bound}. Our proof is inspired by that of Theorem 5 of \cite{chen2023improved}, but we improve their dependence on the data dimension $d$ by applying the stochastic localization technique introduced in \cite{bentonnearly}; see Appendix \ref{sec: score_discretization_error} for the complete proof.

\begin{lemma}\label{lemma: score_discretization_error_bound}
