We adapt the proof of Proposition 4 of \cite{bentonnearly} to our setting where the forward OU process is time-inhomogeneous. Recall that $q_{\tau | 0}(\cdot | \mathbf{y}(0),  \mathbf{c})$ is the conditional distribution of $\mathbf{Y}(\tau)$ given $\mathbf{Y}(0) = \mathbf{y}(0)$ under condition $\mathbf{c}$, and $q_{\tau | 0}(\cdot | \mathbf{y}(0),  \mathbf{c}) \sim \mathcal{N}(\lambda_\tau \mathbf{Y}(0), \sigma_\tau^2I_d)$ from \eqref{eq: DDPM_conditional_relation} and \eqref{eq: forward_SDE_coeff}. Then, one can directly compute that
\begin{align*}
    \text{KL}(q_{\tau | 0}(\cdot | \mathbf{y}(0),  \mathbf{c}) || \mathcal{N}(0, I_d)) = \frac{1}{2}\big(d\log\sigma_\tau^{-2} - d + d\sigma_\tau^2 + \|\lambda_\tau\mathbf{y}(0)\|^2\big).
\end{align*}
By the convexity of the KL divergence and Jensen's inequality, we have
\begin{align*}
    \text{KL}\big(q_{T_g}(\cdot | \mathbf{c}) || \mathcal{N}(0, I_d)\big) &= \text{KL}\bigg(\int_{\mathbf{y}(0)\in\mathbb{R}^d} q_{T_g | 0}(\cdot | \mathbf{y}(0), \mathbf{c}) \mathrm{d} q_0(\mathbf{y}(0) | \mathbf{c}) \bigg|\bigg| \mathcal{N}(0, I_d)\bigg)\\
    &\le \int_{\mathbf{y}(0)\in\mathbb{R}^d}\text{KL}\big(q_{T_g | 0}(\cdot | \mathbf{y}(0), \mathbf{c}) || \mathcal{N}(0, I_d)\big)\mathrm{d} q_0(\mathbf{y}(0) | \mathbf{c})\\
    & =\frac{1}{2}\bigg(d\log\sigma_{T_g}^{-2} - d + d\sigma_{T_g}^2 + \lambda_{T_g}^2\mathbb{E}_{\mathbf{Y}(0)\sim q_{0}(\cdot | \mathbf{c})}\|\mathbf{Y}(0)\|^2\bigg)\\
    &\lesssim de^{-aT_g^2 - 2bT_g} + e^{-\frac{a}{2}T_g^2 - bT_g}\big(\mathbb{E}_{\mathbf{Y}(0)\sim p_{\text{target}}(\cdot | \mathbf{c})}\|\mathbf{Y}(0)\|^2\big)
\end{align*}
where we use \eqref{eq: forward_SDE_coeff} and the approximation that $-\ln(1 - x)\lesssim x + \frac{x^2}{2}$ for $x\in(-1, 1)$. Applying condition \eqref{eq: convergence_finite_moment}, we immediately obtain
\begin{align*}
    \mathbb{E}_{\mathbf{c}\sim\mathbf{C}}\bigg[\text{KL}\big(q_{T_g}(\cdot | \mathbf{c}) || \mathcal{N}(0, I_d)\big)\bigg] \lesssim e^{-\frac{a}{2}T_g^2 - bT_g}\big[M_2 + de^{-\frac{a}{2}T_g^2 - bT_g}\big].
\end{align*}
This completes the proof of Lemma \ref{lemma: initial_dist_error_bound}.

