    &= \mathbb{E}_{\mathbf{Y}(\tau)\sim q_\tau(\cdot | \mathbf{c}), (\mathbf{B})} \bigg[\bigg|\bigg|\int_{\tau}^{\tau_k}u(s)\mathbf{Y}(s)\mathrm{d} s + \int_{\tau}^{\tau_k}v(s)\mathrm{d}\mathbf{B}(s)\bigg|\bigg|^2\bigg] \\
    &\lesssim \mathbb{E}_{\mathbf{Y}(\tau)\sim q_\tau(\cdot | \mathbf{c}), (\mathbf{B})} \bigg[\bigg|\bigg|\int_{\tau}^{\tau_k}u(s)\mathbf{Y}(s)\mathrm{d} s\bigg|\bigg|^2 + \bigg|\bigg|\int_{\tau}^{\tau_k}v(s)\mathrm{d}\mathbf{B}(s)\bigg|\bigg|^2\bigg] \\
