    &\mathbb{E}_{\mathbf{Y}(\tau)\sim q_\tau(\cdot | \mathbf{c}), \mathbf{Y}(\tau_k)\sim q_{\tau_k | \tau}(\cdot | \mathbf{Y}(\tau), \mathbf{c})}\big[\|\nabla\log q_{\tau}(\mathbf{Y}(\tau) | \mathbf{c}) - \nabla\log q_{\tau_k}(\mathbf{Y}(\tau_k) | \mathbf{c} ) \|^2\big]\\
    &\le \int_{\tau}^{\tau_k} f(s)d\sigma^{-2}_{\tau_k} + g^2(s)d\sigma^{-4}_{s} \mathrm{d} s\\
    &\qquad + \sigma_{\tau_k}^{-4}\mathbb{E}_{\mathbf{Y}(\tau_k)\sim q_{\tau_k}(\cdot | \mathbf{c})}[\text{trace}(\boldsymbol{\Sigma}_{\tau_k}(\mathbf{Y}(\tau_k), \mathbf{c}))] - \sigma_{\tau}^{-4}\mathbb{E}_{\mathbf{Y}(\tau)\sim q_\tau(\cdot | \mathbf{c})}[\text{trace}(\boldsymbol{\Sigma}_{\tau}(\mathbf{Y}(\tau), \mathbf{c}))].
\end{align*}

For notational simplicity, we introduce
\begin{align*}
    \tau'_{k_0 - 1} = s,\ \tau'_{k} = \tau_k,\ \text{for }k=k_0, \cdots, K,
\end{align*}
which means that $\tau_{k}' - \tau_{k - 1}' \le \Delta\tau$ for any $k=k_0, \cdots, K$.

Now, given the condition $\mathbf{c}$, note that for $\mathbf{Y}(\tau)\sim q_\tau(\cdot | \mathbf{c})$ and $\mathbf{Y}(\tau_k')\sim q_{\tau_k' | \tau}(\cdot | \mathbf{Y}(\tau), \mathbf{c})$,
\begin{align*}
    & \mathbb{E}_{(\mathbf{Y}(\tau), \mathbf{Y}(\tau_k'))} \big[\|g^2(\tau)\nabla\log q_\tau(\mathbf{Y}(\tau) | \mathbf{c}) - g^2(\tau_k')\nabla\log q_{\tau_k'}(\mathbf{Y}(\tau_k') | \mathbf{c})\|^2\big]\\
    &\le 2\mathbb{E}_{\mathbf{Y}(\tau)}\big[\|(g^2(\tau) - g^2(\tau_k'))\nabla\log q_\tau(\mathbf{Y}(\tau) | \mathbf{c})\|^2]\\
    &\qquad  + 2\mathbb{E}_{(\mathbf{Y}(\tau), \mathbf{Y}(\tau_k'))} \big[g^4(\tau_k')\|\nabla\log q_\tau(\mathbf{Y}(\tau) | \mathbf{c}) - \nabla\log q_{\tau_k'}(\mathbf{Y}(\tau_k') | \mathbf{c})\|^2\big]\\
    &\lesssim d(\Delta\tau)^2\sigma_\tau^{-2} +  \mathbb{E}_{(\mathbf{Y}(\tau), \mathbf{Y}(\tau_k'))} \big[g^4(\tau_k')\|\nabla\log q_\tau(\mathbf{Y}(\tau) | \mathbf{c}) - \nabla\log q_{\tau_k'}(\mathbf{Y}(\tau_k') | \mathbf{c})\|^2\big],
\end{align*}
where the last inequality is from Lemma \ref{lemma: score_function_norm_bound}. Then, since $\tau_k' = \tau_k$ for $k\ge k_0$, by Lemma \ref{lemma: stochastic_char_score_diff} we have
\begin{align}
    & \int_{s}^{\tau_{k_0}}\mathbb{E}_{\mathbf{Y}(\tau)\sim q_\tau(\cdot | \mathbf{c}), \mathbf{Y}(\tau_{k_0})\sim q_{\tau_{k_0} | \tau}(\cdot | \mathbf{Y}(\tau), \mathbf{c})}\big[\|g^2(\tau)\nabla\log q_{\tau}(\mathbf{Y}(\tau) | \mathbf{c}) - g^2(\tau_{k_0})\nabla\log q_{\tau_{k_0}}(\mathbf{Y}(\tau_{k_0}) | \mathbf{c} ) \|^2\big] \mathrm{d}\tau\nonumber\\
    &\qquad + \sum_{k=k_0 + 1}^{K}\int_{\tau_{k - 1}}^{\tau_k}\mathbb{E}_{(\mathbf{Y}(\tau), \mathbf{Y}(\tau_k))}\big[\|g^2(\tau)\nabla\log q_\tau(\mathbf{Y}(\tau) | \mathbf{c}) - g^2(\tau_k)\nabla\log q_{\tau_k}(\mathbf{Y}(\tau_k) | \mathbf{c})\|^2\big]\mathrm{d} \tau \nonumber\\
    &=\sum_{k=k_0}^{K}\int_{\tau_{k - 1}'}^{\tau_k'}\mathbb{E}_{(\mathbf{Y}(\tau), \mathbf{Y}(\tau_k'))}\big[\|g^2(\tau)\nabla\log q_\tau(\mathbf{Y}(\tau) | \mathbf{c}) - g^2(\tau_k')\nabla\log q_{\tau_k'}(\mathbf{Y}(\tau_k') | \mathbf{c})\|^2\big]\mathrm{d} \tau \nonumber\\
    & \lesssim \sum_{k=k_0}^{K} \int_{\tau_{k -1}'}^{\tau_k'} \bigg[d(\Delta\tau)^2\sigma_\tau^{-2}  + \int_{\tau}^{\tau_k'}g^4(\tau_k')f(s)d\sigma^{-2}_{\tau_k'} + g^4(\tau_k')g^2(s)d\sigma^{-4}_{s} \mathrm{d} s \bigg]\mathrm{d} \tau \label{eq: score_diff_part_1}\\
    &\qquad  + \sum_{k=k_0}^{K}\int_{\tau_{k - 1}'}^{\tau_k'} g^4(\tau_k')\big(\sigma_{\tau_k'}^{-4}\mathbb{E}_{\mathbf{Y}(\tau_k')}[\text{trace}(\boldsymbol{\Sigma}_{\tau_k'})] - \sigma_{\tau}^{-4}\mathbb{E}_{\mathbf{Y}(\tau)}[\text{trace}(\boldsymbol{\Sigma}_{\tau})]\big) \mathrm{d}\tau, \label{eq: score_diff_part_2}
\end{align}
where we omit the dependency of $\boldsymbol{\Sigma}_\tau$ on $\mathbf{Y}(\tau)$ and $\mathbf{c}$ for simplicity since the context is clear.



We first bound \eqref{eq: score_diff_part_1}. Recall that $f(\tau) = \frac{1}{2}(a\tau + b), g(\tau) = \sqrt{a\tau + b}$. In addition, $\sigma_\tau^{-2}$ is decreasing in $\tau$ from \eqref{eq: forward_SDE_coeff} and we have its approximation based on \eqref{eq: expoenetial_approximation}. Then
\begin{align}
    &\sum_{k=k_0}^{K} \int_{\tau_{k -1}'}^{\tau_k'} \bigg[d(\Delta\tau)^2\sigma_\tau^{-2}  + \int_{\tau}^{\tau_k'}g^4(\tau_k')f(s)d\sigma^{-2}_{\tau_k'} + g^4(\tau_k')g^2(s)d\sigma^{-4}_{s} \mathrm{d} s \bigg]\mathrm{d} \tau \nonumber\\
    &\lesssim \sum_{k=k_0}^{K}\int_{\tau_{k - 1}'}^{\tau_k'} \bigg[d(\Delta\tau)^2\sigma_{\tau_{k - 1}'}^{-2} + \int_{\tau}^{\tau_k'} g^4(\tau_k')f(\tau_k')d\sigma^{-2}_{\tau_{k - 1}'} + g^4(\tau_k')g^2(\tau_k')d\sigma^{-4}_{\tau_{k - 1}'} \mathrm{d} s \bigg]\mathrm{d} \tau \nonumber\\
    &\lesssim \sum_{k=k_0}^{k_1} \bigg[\frac{d(\Delta\tau)^3}{a(\tau_{k - 1}')^2/2 + b\tau_{k - 1}'}+ \frac{d(\Delta\tau)^2(a\tau_k' + b)^3}{a(\tau_{k - 1}')^2/2 + b\tau_{k - 1}'} + \frac{d(\Delta\tau)^2(a\tau_k' + b)^3}{[a(\tau_{k - 1}')^2/2 + b\tau_{k - 1}']^2}\bigg] + \sum_{k_1 + 1}^{K} d(\Delta\tau)^2(a\tau_k' + b)^3\nonumber\\
    &\lesssim d\Delta\tau\int_{\tau_{k_0 - 1}'}^{\tau_{k_1}'}  \bigg[1 + \tau + \frac{1}{\tau} + \frac{1}{\tau^2}\bigg] \mathrm{d}\tau + d\Delta\tau\int_{\tau_{k_1}'}^{T_g}  (\tau + 1)^3 \mathrm{d}\tau\nonumber\\
    &\lesssim d\Delta\tau\bigg[\ln\bigg(\frac{1}{\tau_{k_0 - 1}'} \bigg) + \frac{1}{\tau_{k_0 - 1}'} + (T_g + 1)^4 \bigg]\nonumber\\
    &= d\Delta\tau\bigg[\ln\bigg(\frac{1}{s} \bigg) + \frac{1}{s} + (T_g + 1)^4 \bigg].\label{eq: score_diff_bound_1}
\end{align}

We next bound \eqref{eq: score_diff_part_2}. Noting that both $\sigma_\tau^2$ and $\mathbb{E}_{\mathbf{Y}(\tau)}[\text{trace}(\boldsymbol{\Sigma}_{\tau})]$ are increasing in $\tau$ (see \eqref{eq: posterior_cov_trace_dt} and the discussion thereafter), we  rearrange the summation to have
\begin{align}
    &\sum_{k=k_0}^{K}\int_{\tau_{k - 1}'}^{\tau_k'}g^4(\tau_k') \big(\sigma_{\tau_k'}^{-4}\mathbb{E}_{\mathbf{Y}(\tau_k')}[\text{trace}(\boldsymbol{\Sigma}_{\tau_k}')] - \sigma_{\tau}^{-4}\mathbb{E}_{\mathbf{Y}(\tau)}[\text{trace}(\boldsymbol{\Sigma}_{\tau})]\big)\mathrm{d}\tau \nonumber\\
    &\le \sum_{k=k_0}^{K}g^4(\tau_k')\Delta\tau \big(\sigma_{\tau_k'}^{-4}\mathbb{E}_{\mathbf{Y}(\tau_k')}[\text{trace}(\boldsymbol{\Sigma}_{\tau_k'})] - \sigma_{\tau_k'}^{-4}\mathbb{E}_{\mathbf{Y}(\tau_{k - 1}')}[\text{trace}(\boldsymbol{\Sigma}_{\tau_{k - 1}'})]\big)\nonumber\\
    &\lesssim  \sum_{k=k_0 - 1}^{k_1} \Delta\tau\mathbb{E}_{\mathbf{Y}(\tau_k')}[\text{trace}(\boldsymbol{\Sigma}_{\tau_k'})] \big(g^4(\tau_k')\sigma_{\tau_k'}^{-4} - g^4(\tau_{k + 1}')\sigma_{\tau_{k + 1}'}^{-4}\big) \nonumber\\
    &\qquad + g^4(T_g)\sigma_{\tau_{k_1}'}^{-4}\Delta\tau \mathbb{E}_{\mathbf{Y}(\tau_{k_1 + 1}')}[\text{trace}(\boldsymbol{\Sigma}_{\tau_{k_1 + 1}'})]  \nonumber\\
    &\qquad + g^4(T_g)\sigma_{\tau_{k_1}'}^{-4}\Delta\tau \bigg[\sum_{k=k_1 + 2}^{K}\big(\mathbb{E}_{\mathbf{Y}(\tau_{k}')}[\text{trace}(\boldsymbol{\Sigma}_{\tau_{k}'})] - \mathbb{E}_{\mathbf{Y}(\tau_{k - 1}')}[\text{trace}(\boldsymbol{\Sigma}_{\tau_{k - 1}'})]\big)\bigg] \nonumber\\
    &\overset{\eqref{eq: expoenetial_approximation}}{\lesssim} \Delta\tau(T_g + 1)^2\mathbb{E}_{\mathbf{Y}(T_g)}[\text{trace}(\boldsymbol{\Sigma}_{T_g})] \nonumber\\
    &\qquad +\sum_{k=k_0 - 1}^{k_1} \Delta\tau\mathbb{E}_{\mathbf{Y}(\tau_k')}[\text{trace}(\boldsymbol{\Sigma}_{\tau_k'})]\bigg[\frac{(a\tau_k' + b)^2}{[a(\tau_k')^2/2 + b\tau_k']^{2}} - \frac{(a\tau_{k + 1}' + b)^2}{[a(\tau_{k + 1}')^2/2 + b\tau_{k + 1}']^{2}}\bigg] \nonumber\\
    &\lesssim \Delta\tau(T_g + 1)^2\mathbb{E}_{\mathbf{Y}(T_g)}[\text{trace}(\boldsymbol{\Sigma}_{T_g})] + \sum_{k=k_0 - 1}^{k_1} \Delta\tau\mathbb{E}_{\mathbf{Y}(\tau_k')}[\text{trace}(\boldsymbol{\Sigma}_{\tau_k'})]\cdot\bigg[\frac{1}{(\tau_k')^2} - \frac{1}{(\tau_{k + 1}')^2}\bigg] \nonumber\\
    &\lesssim \Delta\tau(T_g + 1)^2\mathbb{E}_{\mathbf{Y}(T_g)}[\text{trace}(\boldsymbol{\Sigma}_{T_g})] + \sum_{k=k_0 - 1}^{k_1} \frac{(\Delta\tau)^2}{(\tau_k')^3}\cdot\mathbb{E}_{\mathbf{Y}(\tau_k')}[\text{trace}(\boldsymbol{\Sigma}_{\tau_k'})]. \label{eq: posterior_trace_diff}
\end{align}
Recall that $\boldsymbol{\Sigma}_{\tau} = \boldsymbol{\Sigma}_{\tau}(\mathbf{Y}(\tau), \mathbf{c})$ is the conditional variance of $\mathbf{Y}(0)$ given $\mathbf{Y}(\tau)$ and $\mathbf{c}$. Then
\begin{align}\label{eq: posterior_trace_bound_1}
    \mathbb{E}_{\mathbf{Y}(T_g)}[\text{trace}(\boldsymbol{\Sigma}_{T_g})] \le \mathbb{E}_{\mathbf{Y}(T_g)}\big[\mathbb{E}_{\mathbf{Y}(0)|\mathbf{Y}(T_g)}\|\mathbf{Y}(0)\|^2\big] = \mathbb{E}_{\mathbf{Y}(0)\sim p_{\text{target}}(\cdot | \mathbf{c})}\big[\|\mathbf{Y}(0)\|^2\big].
\end{align}
On the other hand, $\mathbf{Y}(\tau) | \mathbf{Y}(0) \sim \mathcal{N}\big(\lambda_\tau\mathbf{Y}(0), \sigma_\tau^2I_d\big)$ from \eqref{eq: DDPM_conditional_relation}. Then, for $\tau < \tau_{k_1}' = \tau_{k_1}$ in \eqref{eq: expoenential_threshold}, using a similar approximation as in \eqref{eq: expoenetial_approximation} we have
\begin{align}
    \mathbb{E}_{\mathbf{Y}(\tau)}[\text{trace}(\boldsymbol{\Sigma}_{\tau})] &= \mathbb{E}_{\mathbf{Y}(\tau)}\big[\text{trace}\big({\text{Cov}}_{\mathbf{Y}(0)|\mathbf{Y}(\tau)}[\mathbf{Y}(0)]\big)\big]\nonumber\\
    &=\lambda_{\tau}^{-2}\mathbb{E}_{\mathbf{Y}(\tau)} \big[\text{trace}\big({\text{Cov}}_{\mathbf{Y}(0)|\mathbf{Y}(\tau)}[\lambda_{\tau}\mathbf{Y}(0) - \mathbf{Y}(\tau)]\big)\big] \nonumber\\
    &\le \lambda_{\tau}^{-2}\mathbb{E}_{(\mathbf{Y}(0), \mathbf{Y}(\tau))} \big[\|\lambda_{\tau}\mathbf{Y}(0) - \mathbf{Y}(\tau)\|^2\big] \nonumber\\
    &= \lambda_\tau^{-2}d\sigma_\tau^2 = d\big(e^{a\tau^2/2 + b\tau} - 1\big)\nonumber\\
    &\asymp d(a\tau^2/2 + b\tau). \label{eq: posterior_trace_bound_2}
\end{align}
Substituting \eqref{eq: posterior_trace_bound_1} and \eqref{eq: posterior_trace_bound_2} into \eqref{eq: posterior_trace_diff}, we have
\begin{align}
    &\sum_{k=k_0}^{K}\int_{\tau_{k - 1}'}^{\tau_k'}g^4(\tau_k') \big(\sigma_{\tau_k'}^{-4}\mathbb{E}_{\mathbf{Y}(\tau_k')}[\text{trace}(\boldsymbol{\Sigma}_{\tau_k'})] - \sigma_{\tau}^{-4}\mathbb{E}_{\mathbf{Y}(\tau)}[\text{trace}(\boldsymbol{\Sigma}_{\tau})]\big)\mathrm{d}\tau \nonumber\\
    &\lesssim  \Delta\tau(T_g + 1)^2 \mathbb{E}_{\mathbf{Y}(0)}\big[\|\mathbf{Y}(0)\|^2\big] + \sum_{k=k_0 - 1}^{k_1} \frac{(\Delta\tau)^2d[a(\tau_k')^2/2 + b\tau_k'
    ]}{(\tau_k')^3} \nonumber \\
    &\lesssim \Delta\tau(T_g + 1)^2 \mathbb{E}_{\mathbf{Y}(0)}\big[\|\mathbf{Y}(0)\|^2\big]  + d\Delta\tau  \int_{\tau_{k_0 - 1}'}^{\tau_{k_1}'}\bigg[\frac{1}{\tau} + \frac{1}{\tau^2}\bigg] \mathrm{d}\tau \nonumber\\
    &\lesssim \Delta\tau(T_g + 1)^2\mathbb{E}_{\mathbf{Y}(0)}\big[\|\mathbf{Y}(0)\|^2\big]  + d\Delta\tau\bigg[\ln\bigg(\frac{1}{\tau_{k_0 - 1}'} \bigg) + \frac{1}{\tau_{k_0 - 1}'}\bigg]\nonumber\\
    &= \Delta\tau(T_g + 1)^2\mathbb{E}_{\mathbf{Y}(0)\sim p_{\text{target}}(\cdot | \mathbf{c})}\big[\|\mathbf{Y}(0)\|^2\big]  + d\Delta\tau\bigg[\ln\bigg(\frac{1}{s} \bigg) + \frac{1}{s}\bigg]. \label{eq: score_diff_bound_2}
\end{align}
The proof is complete by combining \eqref{eq: score_diff_bound_1} and \eqref{eq: score_diff_bound_2}.

