    &\lesssim d\Delta\tau\int_{\tau_{k_0 - 1}'}^{\tau_{k_1}'}  \bigg[1 + \tau + \frac{1}{\tau} + \frac{1}{\tau^2}\bigg] \mathrm{d}\tau + d\Delta\tau\int_{\tau_{k_1}'}^{T_g}  (\tau + 1)^3 \mathrm{d}\tau\nonumber\\
    &\lesssim d\Delta\tau\bigg[\ln\bigg(\frac{1}{\tau_{k_0 - 1}'} \bigg) + \frac{1}{\tau_{k_0 - 1}'} + (T_g + 1)^4 \bigg]\nonumber\\
    &= d\Delta\tau\bigg[\ln\bigg(\frac{1}{s} \bigg) + \frac{1}{s} + (T_g + 1)^4 \bigg].\label{eq: score_diff_bound_1}
\end{align}

