    \mathbb{E}_{\mathbf{Y}(\tau)}[\text{trace}(\boldsymbol{\Sigma}_{\tau})] &= \mathbb{E}_{\mathbf{Y}(\tau)}\big[\text{trace}\big({\text{Cov}}_{\mathbf{Y}(0)|\mathbf{Y}(\tau)}[\mathbf{Y}(0)]\big)\big]\nonumber\\
