    &\lesssim  \Delta\tau(T_g + 1)^2 \mathbb{E}_{\mathbf{Y}(0)}\big[\|\mathbf{Y}(0)\|^2\big] + \sum_{k=k_0 - 1}^{k_1} \frac{(\Delta\tau)^2d[a(\tau_k')^2/2 + b\tau_k'
    ]}{(\tau_k')^3} \nonumber \\
    &\lesssim \Delta\tau(T_g + 1)^2 \mathbb{E}_{\mathbf{Y}(0)}\big[\|\mathbf{Y}(0)\|^2\big]  + d\Delta\tau  \int_{\tau_{k_0 - 1}'}^{\tau_{k_1}'}\bigg[\frac{1}{\tau} + \frac{1}{\tau^2}\bigg] \mathrm{d}\tau \nonumber\\
    &\lesssim \Delta\tau(T_g + 1)^2\mathbb{E}_{\mathbf{Y}(0)}\big[\|\mathbf{Y}(0)\|^2\big]  + d\Delta\tau\bigg[\ln\bigg(\frac{1}{\tau_{k_0 - 1}'} \bigg) + \frac{1}{\tau_{k_0 - 1}'}\bigg]\nonumber\\
