\end{align}

\label{lemma: hessian_score_bound}
    For any given condition $\mathbf{c}$ and any $\tau \in (0, T_g]$, we have
    \begin{align*}
        \mathbb{E}_{\mathbf{Y}(\tau)\sim q_\tau(\cdot | \mathbf{c})}\big[\|\nabla^2\log q_\tau(\mathbf{Y}_\tau|\mathbf{c})\|_F^2\big]\le d\sigma_\tau^{-4} + \frac{1}{g^2(\tau)}\cdot \frac{\mathrm{d}}{\mathrm{d}\tau}\bigg(\sigma_\tau^{-4}\mathbb{E}_{\mathbf{Y}(\tau)\sim q_\tau(\cdot | \mathbf{c})}[\text{trace}(\boldsymbol{\Sigma}_\tau(\mathbf{Y}(\tau), \mathbf{c}))]\bigg).
    \end{align*}

\begin{align*}
        \mathbb{E}_{\mathbf{Y}(\tau)\sim q_\tau(\cdot | \mathbf{c})}\big[\|\nabla^2\log q_\tau(\mathbf{Y}_\tau|\mathbf{c})\|_F^2\big]\le d\sigma_\tau^{-4} + \frac{1}{g^2(\tau)}\cdot \frac{\mathrm{d}}{\mathrm{d}\tau}\bigg(\sigma_\tau^{-4}\mathbb{E}_{\mathbf{Y}(\tau)\sim q_\tau(\cdot | \mathbf{c})}[\text{trace}(\boldsymbol{\Sigma}_\tau(\mathbf{Y}(\tau), \mathbf{c}))]\bigg).
    \end{align*}

Following \cite{bentonnearly}, we first consider the stochastic dynamic of the score function $\big\{\nabla\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c} ): \tau\in[0, T_g)\big\}$ under a given condition $\mathbf{c}$.  Recall that the reverse SDE \eqref{eq: reverse_SDE_DDPM} of diffusion models is
\begin{align*}
     \mathrm{d}\tilde{\mathbf{Y}}(\tau) = [\tilde f(\tau)\tilde{\mathbf{Y}}(\tau) + \tilde g^2(\tau) \nabla\log q_{T_g - \tau}(\tilde {\mathbf{Y}}(\tau) | \mathbf{c})]\mathrm{d}\tau + \tilde g(\tau) \mathrm{d}\tilde{\mathbf{B}}(\tau),
\end{align*}
where $\tilde f(\tau) := f(T_g - \tau)$ and $\tilde g(\tau) := g(T_g - \tau)$. 
As in the proof of Lemma 3 of \cite{bentonnearly}, $\nabla\log q_{T_g - \tau}(\cdot | \mathbf{c})$ is smooth for $\tau\in[0, T_g)$, and by It\^{o}'s formula we can write
\begin{align}
        \mathrm{d}\big[\nabla\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c} )\big] &= \bigg\{\nabla^2\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c} )\cdot\big[\tilde f(\tau)\tilde{\mathbf{Y}}(\tau) + \tilde g^2(\tau) \nabla\log q_{T_g - \tau}(\tilde {\mathbf{Y}}(\tau) | \mathbf{c})\big]\nonumber\\
        &\qquad \quad + \frac{1}{2}\tilde g^2(\tau)\cdot \Delta \big(\nabla\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c} )\big)\bigg\}\mathrm{d}\tau + \frac{\mathrm{d}\big[\nabla\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c} )\big]}{\mathrm{d} \tau} \mathrm{d} \tau \nonumber\\
        &\qquad +  \tilde g(\tau)\nabla^2\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c} ) \mathrm{d}\tilde{\mathbf{B}}(\tau).\label{eq: score_function_ito}
\end{align}
To further simplify \eqref{eq: score_function_ito}, consider the Fokker–Planck equation for the forward process \eqref{eq: forward_SDE_DDPM}:
\begin{align*}
    \mathrm{d} q_\tau(\mathbf{y} | \mathbf{c}) = \bigg(-\nabla\cdot\big[(-f(\tau)q_\tau(\mathbf{y} | \mathbf{c})\mathbf{y} \big] + \frac{1}{2}\Delta\big[g^2(\tau)q_\tau(\mathbf{y}|\mathbf{c})\big]\bigg)\mathrm{d}\tau,
\end{align*}
leading to
\begin{align*}
    \mathrm{d}(\log q_\tau(\mathbf{y} | \mathbf{c})) &= \frac{1}{q_\tau(\mathbf{y} | \mathbf{c})}\bigg(-\nabla\cdot\big[(-f(\tau) q_\tau(\mathbf{y} | \mathbf{c})\mathbf{y}\big] + \frac{1}{2} \Delta\big[g^2(\tau)q_\tau(\mathbf{y}|\mathbf{c})\big]\bigg)\mathrm{d}\tau\\
    &= \bigg(f(\tau)d + f(\tau)\mathbf{y}^T\nabla\log q_\tau(\mathbf{y} | \mathbf{c}) + \frac{1}{2}g^2(\tau)\Delta\log  q_\tau(\mathbf{y} | \mathbf{c}) + \frac{1}{2}g^2(\tau)\|\nabla\log q_\tau(\mathbf{y} | \mathbf{c})\|^2\bigg)\mathrm{d} \tau.
\end{align*}
It follows that
\begin{equation}\label{eq: score_function_time_derivative}
    \begin{split}
        &\frac{\mathrm{d}\big[\nabla\log q_{T_g - \tau}(\mathbf{y} | \mathbf{c} )\big]}{\mathrm{d} \tau} = \nabla\frac{\mathrm{d}(\log q_{T_g - \tau}(\mathbf{y} | \mathbf{c}))}{\mathrm{d} \tau} \\
        &= -\bigg(\tilde f(\tau)\nabla\log q_{T_g - \tau}(\mathbf{y} | \mathbf{c}) + \tilde f(\tau)\nabla^2\log q_{T_g - \tau}(\mathbf{y} | \mathbf{c})\cdot\mathbf{y} \\
        & \quad \qquad + \frac{1}{2}\tilde g^2(\tau)\nabla\big(\Delta\log  q_{T_g - \tau}(\mathbf{y} | \mathbf{c})\big) + \tilde g^2(\tau)\nabla^2\log q_{T_g - \tau}(\mathbf{y} | \mathbf{c})\cdot \nabla\log q_{T_g - \tau}(\mathbf{y} | \mathbf{c})\bigg).
    \end{split}
\end{equation}
Substituting \eqref{eq: score_function_time_derivative} into \eqref{eq: score_function_ito} and simplifying, we obtain
\begin{align}\label{eq: score_function_process}
    \mathrm{d}\big[\nabla\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c} )\big] = -\tilde f(\tau)\nabla\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c}) \mathrm{d} \tau + \tilde g(\tau)\nabla^2\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c} ) \mathrm{d}\tilde{\mathbf{B}}(\tau).
\end{align}

Now, we establish the desired bound. First, for  fixed $s \in (0, \tau)$, we have
\begin{align*}
    &\mathrm{d}\big[(\nabla\log q_{T_g - s}(\tilde{\mathbf{Y}}(s) | \mathbf{c} ))^T\nabla\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c} )\big] \\
    &= -\tilde f(\tau)(\nabla\log q_{T_g - s}(\tilde{\mathbf{Y}}(s) | \mathbf{c} ))^T\nabla\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c}) \mathrm{d} \tau \\
    &\qquad + \tilde g(\tau)(\nabla\log q_{T_g - s}(\tilde{\mathbf{Y}}(s) | \mathbf{c} ))^T\nabla^2\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c} ) \mathrm{d}\tilde{\mathbf{B}}(\tau).
\end{align*}
By Lemma \ref{lemma: hessian_score_bound}, $\int_{s}^\tau \mathbb{E}_{\tilde{\mathbf{Y}}(u)}\big[\|\nabla^2\log q_{T_g - u}(\tilde{\mathbf{Y}}(u))\|^2_F\big]\mathrm{d} u < \infty$ where $\tilde{\mathbf{Y}}(u)\sim q_{T_g - u}(\cdot | \mathbf{c})$, implying that the final term in the above equation is a square-integrable martingale. Integrating on both sides and taking expectations w.r.t. the joint distribution of $(\tilde{\mathbf{Y}}(\tau), \tilde{\mathbf{Y}}(s))$ induced by  \eqref{eq: reverse_SDE_DDPM}, we get
\begin{equation}\label{eq: score_process_corss_term_dt}
    \begin{split}
        &\frac{\mathrm{d}}{\mathrm{d}\tau}\mathbb{E}_{(\tilde{\mathbf{Y}}(\tau), \tilde{\mathbf{Y}}(s))}\big[(\nabla\log q_{T_g - s}(\tilde{\mathbf{Y}}(s) | \mathbf{c} ))^T\nabla\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c} )\big]\\
        &= -\mathbb{E}_{(\tilde{\mathbf{Y}}(\tau), \tilde{\mathbf{Y}}(s))}\big[\tilde f(\tau)(\nabla\log q_{T_g - s}(\tilde{\mathbf{Y}}(s) | \mathbf{c} ))^T\nabla\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c}) \big].
    \end{split}
\end{equation}

Next, if setting $\tilde\Lambda(\tau) = \exp\big(\int_0^\tau \tilde f(s)\mathrm{d} s \big)$ and  applying It\^{o}'s formula to \eqref{eq: score_function_process}, we obtain
\begin{align*}
    \mathrm{d}\big[\tilde\Lambda(\tau)\nabla\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c} )\big] = \tilde\Lambda(\tau)\tilde g(\tau)\nabla^2\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c} ) \mathrm{d}\tilde{\mathbf{B}}(\tau).
\end{align*}
We know from Lemma \ref{lemma: hessian_score_bound} that $\int_{s}^\tau\tilde\Lambda^2(u)\mathbb{E}_{\tilde{\mathbf{Y}}(u)} \big[\|\nabla^2\log q_{T_g - u}(\tilde{\mathbf{Y}}(u))\|^2_F\big]\mathrm{d} u < \infty$ for any fixed $s > 0$. By It\^{o}'s isometry and chain rule, we obtain
\begin{align*}
    &\tilde\Lambda^2(\tau)\tilde g^2(\tau)\mathbb{E}_{\tilde{\mathbf{Y}}(\tau)}\big[\|\nabla^2\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c})\|^2_F\big]\\
    &= \frac{\mathrm{d}}{\mathrm{d}\tau}\mathbb{E}_{(\tilde{\mathbf{Y}}(\tau), \tilde{\mathbf{Y}}(s))}\big[\|\tilde\Lambda(\tau)\nabla\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c} ) - \tilde\Lambda(s)\nabla\log q_{T_g - s}(\tilde{\mathbf{Y}}(s) | \mathbf{c} )\|^2\big] \nonumber\\
    &= \tilde\Lambda^2(\tau)\cdot \frac{\mathrm{d}}{\mathrm{d}\tau}\mathbb{E}_{\tilde{\mathbf{Y}}(\tau)}\big[\|\nabla\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c} ) ||^2 + 2\tilde f(\tau)\tilde\Lambda^2(\tau) \mathbb{E}_{\tilde{\mathbf{Y}}(\tau)}\big[\|\nabla\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c} ) ||^2\\
    &\qquad - 2\tilde\Lambda(\tau)\tilde\Lambda(s)\cdot \frac{\mathrm{d}}{\mathrm{d}\tau}\mathbb{E}_{(\tilde{\mathbf{Y}}(\tau), \tilde{\mathbf{Y}}(s))}\big[(\nabla\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c} ))^T\nabla\log q_{T_g - s}(\tilde{\mathbf{Y}}(s) | \mathbf{c} )\big] \\
    &\qquad - 2\tilde f(\tau)\tilde\Lambda(\tau)\tilde\Lambda(s)\mathbb{E}_{(\tilde{\mathbf{Y}}(\tau), \tilde{\mathbf{Y}}(s))}\big[(\nabla\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c} ))^T\nabla\log q_{T_g - s}(\tilde{\mathbf{Y}}(s) | \mathbf{c} )\big]\\
    &\overset{\eqref{eq: score_process_corss_term_dt}}{=}  \tilde\Lambda^2(\tau)\cdot \frac{\mathrm{d}}{\mathrm{d}\tau}\mathbb{E}_{\tilde{\mathbf{Y}}(\tau)}\big[\|\nabla\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c} ) ||^2 + 2\tilde f(\tau)\tilde\Lambda^2(\tau)\mathbb{E}_{\tilde{\mathbf{Y}}(\tau)}\big[\|\nabla\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c} ) ||^2.
\end{align*}
It follows that
\begin{equation}\label{eq: F_norm_characterization}
    \begin{split}
        & \frac{\mathrm{d}}{\mathrm{d}\tau}\mathbb{E}_{\tilde{\mathbf{Y}}(\tau)}\big[\|\nabla\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c} ) ||^2 + 2\tilde f(\tau)\mathbb{E}_{\tilde{\mathbf{Y}}(\tau)}\big[\|\nabla\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c} ) ||^2\\
        &= \tilde g^2(\tau)\mathbb{E}_{\tilde{\mathbf{Y}}(\tau)}\big[\|\nabla^2\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c})\|^2_F\big].
    \end{split}
\end{equation}


For any fixed $s > 0$ and $\tau > s$,  \eqref{eq: score_process_corss_term_dt} and \eqref{eq: F_norm_characterization} lead to
\begin{align*}
    &\frac{\mathrm{d}}{\mathrm{d}\tau}\mathbb{E}_{(\tilde{\mathbf{Y}}(\tau), \tilde{\mathbf{Y}}(s))} \big[\|\nabla\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c} ) - \nabla\log q_{T_g - s}(\tilde{\mathbf{Y}}(s) | \mathbf{c} )\|^2\big]\\
    &= \frac{\mathrm{d}}{\mathrm{d}\tau}\mathbb{E}_{\tilde{\mathbf{Y}}(\tau)}\big[\|\nabla\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c} )\|^2\big] - 2\frac{\mathrm{d}}{\mathrm{d}\tau}\mathbb{E}_{(\tilde{\mathbf{Y}}(\tau), \tilde{\mathbf{Y}}(s))}\big[(\nabla\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c} ))^T\nabla\log q_{T_g - s}(\tilde{\mathbf{Y}}(s) | \mathbf{c} )\big]\\
    &= \tilde g^2(\tau)\mathbb{E}_{\tilde{\mathbf{Y}}(\tau)}\big[\|\nabla^2\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c})\|^2_F\big] - 2\tilde f(\tau)\mathbb{E}_{\tilde{\mathbf{Y}}(\tau)}\big[\|\nabla\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c} ) ||^2\\
    &\qquad + 2\mathbb{E}_{(\tilde{\mathbf{Y}}(\tau), \tilde{\mathbf{Y}}(s))}\big[\tilde f(\tau)(\nabla\log q_{T_g - s}(\tilde{\mathbf{Y}}(s) | \mathbf{c} ))^T\nabla\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c}) \big]\\
    &= \tilde g^2(\tau)\mathbb{E}_{\tilde{\mathbf{Y}}(\tau)}\big[\|\nabla^2\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c})\|^2_F\big] \\
    &\qquad - 2\tilde f(\tau)\mathbb{E}_{(\tilde{\mathbf{Y}}(\tau), \tilde{\mathbf{Y}}(s))}\big[\|\nabla\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c} ) - \nabla\log q_{T_g - s}(\tilde{\mathbf{Y}}(s) | \mathbf{c} )||^2\big]\\
    &\qquad + 2\tilde f(\tau)\mathbb{E}_{(\tilde{\mathbf{Y}}(\tau), \tilde{\mathbf{Y}}(s))} \big[(\nabla\log q_{T_g - s}(\tilde{\mathbf{Y}}(s) | \mathbf{c} ) - \nabla\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c} ))^T\nabla\log q_{T_g - s}(\tilde{\mathbf{Y}}(s) | \mathbf{c} )\big].
\end{align*}
However,  by Young's inequality,
\begin{align*}
    &\mathbb{E}_{(\tilde{\mathbf{Y}}(\tau), \tilde{\mathbf{Y}}(s))}\big[(\nabla\log q_{T_g - s}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c} ) - \nabla\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(s) | \mathbf{c} ))^T\nabla\log q_{T_g - s}(\tilde{\mathbf{Y}}(s) | \mathbf{c} )\big]\\
    &\le \frac{1}{2}\bigg[\mathbb{E}_{(\tilde{\mathbf{Y}}(\tau), \tilde{\mathbf{Y}}(s))}\big[\|\nabla\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c} ) - \nabla\log q_{T_g - s}(\tilde{\mathbf{Y}}(s) | \mathbf{c} )\|^2\big] + \mathbb{E}_{\tilde{\mathbf{Y}}(s)}\big[\|\nabla\log q_{T_g - s}(\tilde{\mathbf{Y}}(s) | \mathbf{c} )\|^2\big]\bigg].
\end{align*}
Therefore, we have
\begin{align*}
    &\frac{\mathrm{d}}{\mathrm{d}\tau}\mathbb{E}_{(\tilde{\mathbf{Y}}(\tau), \tilde{\mathbf{Y}}(s))} \big[\|\nabla\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c} ) - \nabla\log q_{T_g - s}(\tilde{\mathbf{Y}}(s) | \mathbf{c} )\|^2\big]\\
    &\le \tilde f(\tau)\mathbb{E}_{\tilde{\mathbf{Y}}(s)}\big[\|\nabla\log q_{T_g - s}(\tilde{\mathbf{Y}}(s) | \mathbf{c} )\|^2\big] + \tilde g^2(\tau)\mathbb{E}_{\tilde{\mathbf{Y}}(\tau)}\big[\|\nabla^2\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c})\|^2_F\big].
\end{align*}
Let $s=\tau_k$ and $\tau\in[\tau_k, \tau_{k + 1}]$. Integrate both sides of the above equation from $\tau_k$ to $\tau$ and use Lemma \ref{lemma: score_function_norm_bound} and Lemma \ref{lemma: hessian_score_bound} to obtain
\begin{align*}
    &\mathbb{E}_{(\tilde{\mathbf{Y}}(\tau), \tilde{\mathbf{Y}}(\tau_k))}\big[\|\nabla\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau) | \mathbf{c} ) - \nabla\log q_{T_g - \tau_k}(\tilde{\mathbf{Y}}(\tau_k) | \mathbf{c} )\|^2\big]\\
    &\le \int_{\tau_k}^{\tau}\tilde f(u)\mathbb{E}_{\tilde{\mathbf{Y}}(\tau_k)}\big[\|\nabla\log q_{T_g - \tau_k}(\tilde{\mathbf{Y}}(\tau_k) | \mathbf{c} )\|^2\big] + \tilde g^2(u)\mathbb{E}_{\tilde{\mathbf{Y}}(u)}\big[\|\nabla^2\log q_{T_g - u}(\tilde{\mathbf{Y}}(u) | \mathbf{c})\|^2_F\big]\mathrm{d} u\\
    &\le \int_{\tau_k}^{\tau}\tilde f(u)d\sigma^{-2}_{T_g - \tau_k} + \tilde g^2(u)d\sigma^{-4}_{T_g - u} - \frac{\mathrm{d}}{\mathrm{d} r}\big(\sigma_{T - r}^{-4}\mathbb{E}_{\tilde{\mathbf{Y}}(r)\sim q_{T_g - r}(\cdot | \mathbf{c})}[\text{trace}(\boldsymbol{\Sigma}_{T_g - r})]\big)\big|_{r=u} \mathrm{d} u\\
    &\le \int_{\tau_k}^{\tau}\tilde f(u)d\sigma^{-2}_{T_g - \tau_k} + \tilde g^2(u)d\sigma^{-4}_{T_g - u} \mathrm{d} u \\
    &\qquad + \sigma_{T - \tau_k}^{-4}\mathbb{E}_{\mathbf{Y}(T_g - \tau_k)}[\text{trace}(\boldsymbol{\Sigma}_{T_g - \tau_k})] - \sigma_{T - \tau}^{-4}\mathbb{E}_{\mathbf{Y}(T_g - \tau)}[\text{trace}(\boldsymbol{\Sigma}_{T_g - \tau})],
\end{align*}
where we omit to write out the dependency of $\boldsymbol{\Sigma}_\tau$ on $\mathbf{Y}(\tau)$ and $\mathbf{c}$ for simplicity.

Finally, for the forward process $\mathbf{Y}$ in \eqref{eq: forward_SDE_DDPM}, since $\tilde{\mathbf{Y}}(\tau) = \mathbf{Y}(T_g - \tau)$ for any $\tau\in[0, T_g]$, we have for $\tau >0$ and $\tau\in[\tau_{k - 1}, \tau_k]$,
\begin{align*}
    &\mathbb{E}_{(\mathbf{Y}(\tau), \mathbf{Y}(\tau_k))}\big[\|\nabla\log q_{\tau}(\mathbf{Y}(\tau) | \mathbf{c}) - \nabla\log q_{\tau_k}(\mathbf{Y}(\tau_k) | \mathbf{c} ) \|^2\big]\\
    &\le \int_{\tau}^{\tau_k} f(s)d\sigma^{-2}_{\tau_k} + g^2(s)d\sigma^{-4}_{s} \mathrm{d} s + \big(\sigma_{\tau_k}^{-4}\mathbb{E}_{\mathbf{Y}(\tau_k)}[\text{trace}(\boldsymbol{\Sigma}_{\tau_k})] - \sigma_{\tau}^{-4}\mathbb{E}_{\mathbf{Y}(\tau)}[\text{trace}(\boldsymbol{\Sigma}_{\tau})]\big).
\end{align*}
This completes our proof.

