We first prove Lemma \ref{lemma: KL_dt}(a). Consider an auxiliary process $\{\tilde{\mathbf{Y}}^a(\tau): \tau\in(\tau_k, \tau_{k + 1}]\}$, which also starts from $\tilde{\mathbf{Y}}^a(\tau_k) = \tilde{\mathbf{z}}$, with the dynamic
\begin{align}
    \mathrm{d}\tilde{\mathbf{Y}}^a(\tau) &= [\tilde f(\tau_k)\tilde{\mathbf{z}} + \tilde g^2(\tau_k) \nabla\log q_{T_g - \tau_k}(\tilde {\mathbf{z}} | \mathbf{c})]\mathrm{d}\tau + \tilde g(\tau) \mathrm{d}\tilde{\mathbf{B}}(\tau):=\tilde F_a(\tilde{\mathbf{z}})\mathrm{d}\tau + \tilde g(\tau) \mathrm{d} \tilde{\mathbf{B}}(\tau). \label{eq: auxiliary_reverse_SDE}
\end{align}
Denote by $\tilde p_{\tau | \tau_k}^a(\cdot | \tilde{\mathbf{z}})$ the conditional density of $\tilde{\mathbf{Y}}^a(\tau)$  given $\tilde{\mathbf{Y}}^a(\tau_k) = \tilde{\mathbf{z}}$. Then, $\tilde p_{\tau | \tau_k}^a(\cdot | \tilde{\mathbf{z}})$ is a Gaussian density with mean $\tilde {\mathbf{z}} + (\tau - \tau_k)\tilde F_a(\tilde{\mathbf{z}})$ and covariance $\int_{\tau_k}^{\tau}\tilde g^2(s)\mathrm{d} s\cdot I_d$.

Note that, for any $\tau\in(\tau_k, \tau_{k + 1}]$ and $\tilde{\mathbf{z}}\in\mathbb{R}^d$,
\begin{align}
    \text{KL}\big(\tilde p_{\tau | \tau_k}(\cdot | \tilde{\mathbf{z}}) || \tilde p^\theta_{\tau | \tau_k}(\cdot | \tilde{\mathbf{z}})\big)  &= \int_{\mathbb{R}^d} \tilde p_{\tau | \tau_k}(\mathbf{y} | \tilde{\mathbf{z}}) \log\frac{\tilde p_{\tau | \tau_k}(\mathbf{y} | \tilde{\mathbf{z}})}{\tilde p_{\tau | \tau_k}^\theta(\mathbf{y} | \tilde{\mathbf{z}})}\mathrm{d}\mathbf{y}\nonumber\\
    &= \text{KL}\big(\tilde p_{\tau | \tau_k}(\cdot | \tilde{\mathbf{z}}) || \tilde p_{\tau | \tau_k}^a(\cdot | \tilde{\mathbf{z}})\big) + \int_{\mathbb{R}^d} \tilde p_{\tau | \tau_k}(\mathbf{y} | \tilde{\mathbf{z}}) \log\frac{\tilde p_{\tau | \tau_k}^a(\mathbf{y} | \tilde{\mathbf{z}})}{\tilde p^\theta_{\tau | \tau_k}(\mathbf{y} | \tilde{\mathbf{z}})}\mathrm{d}\mathbf{y}. \label{eq: limit_KL_decomposion}
\end{align}


Using a similar argument as in the proof of Lemma 7(2) in \cite{chen2023improved}, we can obtain that, for almost every $\tilde{\mathbf{z}}\in\mathbb{R}^d$,
\begin{align*}
    \lim_{\tau\to\tau_k+}\text{KL}(\tilde p_{\tau | \tau_k}(\cdot | \tilde{\mathbf{z}})|| \tilde p^a_{\tau | \tau_k}(\cdot | \tilde{\mathbf{z}})) = 0.
\end{align*}
It follows that
\begin{align}\label{eq: limit_KL_auxiliary}
    \mathbb{E}_{\tilde{\mathbf{Y}}(\tau_k)\sim \tilde p_{\tau_k}}\bigg[\lim_{\tau\to\tau_k+}\text{KL}(\tilde p_{\tau | \tau_k}(\cdot | \tilde{\mathbf{Y}}(\tau_k))|| \tilde p^a_{\tau | \tau_k}(\cdot | \tilde{\mathbf{Y}}(\tau_k)))\bigg] = 0.
\end{align}



On the other hand, both $\tilde p^a_{\tau | \tau_k}(\cdot | \tilde{\mathbf{z}})$ and $\tilde p^\theta_{\tau | \tau_k}(\cdot | \tilde{\mathbf{z}})$ are Gaussian densities, and  $\int^{\tau}_{\tau_k}\tilde g^2(u) \mathrm{d} u =[\tilde g^2(\tau_k) - a(\tau - \tau_k)/2](\tau - \tau_k) \le \tilde g^2(\tau_k)(\tau - \tau_k)$. Then, for every $\tilde{\mathbf{z}}\in\mathbb{R}^d$,
\begin{align*}
    &\lim_{\tau \to \tau_k+}\int_{\mathbb{R}^d} \tilde p_{\tau | \tau_k}(\mathbf{y} | \tilde{\mathbf{z}}) \log\frac{\tilde p_{\tau | \tau_k}^a(\mathbf{y} | \tilde{\mathbf{z}})}{\tilde p^\theta_{\tau | \tau_k}(\mathbf{y} | \tilde{\mathbf{z}})}\mathrm{d}\mathbf{y}\nonumber\\
    &= \lim_{\tau \to \tau_k+} \int_{\mathbb{R}^d} \tilde p_{\tau | \tau_k}(\mathbf{y} | \tilde{\mathbf{z}})\bigg[ - \frac{\|\mathbf{y} - \tilde{\mathbf{z}} - (\tau - \tau_k)\tilde F_a(\tilde{\mathbf{z}})\|^2}{\int^{\tau}_{\tau_k}\tilde g^2(u)\mathrm{d} u} + \frac{\|\mathbf{y} - \tilde{\mathbf{z}} - (\tau - \tau_k)\tilde F_\theta(\tilde{\mathbf{z}})\|^2}{\tilde g^2(\tau_k)(\tau - \tau_k)}\bigg]\mathrm{d}\mathbf{y}\nonumber\\
    &= \lim_{\tau \to \tau_k+} \int_{\mathbb{R}^d} \tilde p_{\tau | \tau_k}(\mathbf{y} | \tilde{\mathbf{z}}) \frac{\tilde g^2(\tau_k) - a(\tau - \tau_k)/2 - \tilde g^2(\tau_k)}{[\tilde g^2(\tau_k) - a(\tau - \tau_k)/2]\cdot \tilde g^2(\tau_k)(\tau - \tau_k)}\|\mathbf{y} - \tilde{\mathbf{z}}\|^2\mathrm{d}\mathbf{y}\nonumber\\
    &\qquad + \lim_{\tau \to \tau_k+}\int_{\mathbb{R}^d}2\tilde p_{\tau | \tau_k}(\mathbf{y} | \tilde{\mathbf{z}})\bigg[\frac{\tilde F_a(\tilde{\mathbf{z}})}{\tilde g^2(\tau_k) - a(\tau - \tau_k)/2} - \frac{\tilde F_\theta(\tilde{\mathbf{z}})}{\tilde g^2(\tau_k)}\bigg]^T(\mathbf{y} - \tilde{\mathbf{z}})\mathrm{d}\mathbf{y}\nonumber\\
    &\qquad + \lim_{\tau \to \tau_k+}\int_{\mathbb{R}^d}\tilde p_{\tau | \tau_k}(\mathbf{y} | \tilde{\mathbf{z}})\bigg[\frac{\|\tilde F_\theta(\tilde{\mathbf{z}})\|^2(\tau - \tau_k)}{\tilde g^2(\tau_k)} - \frac{\|\tilde F_a(\tilde{\mathbf{z}})\|^2(\tau -\tau_k)}{\tilde g^2(\tau_k) - a(\tau - \tau_k)/2}\bigg]\mathrm{d}\mathbf{y}\nonumber\\
    &\le  \lim_{\tau \to \tau_k+}\int_{\mathbb{R}^d}2\tilde p_{\tau | \tau_k}(\mathbf{y} | \tilde{\mathbf{z}})\bigg[\frac{\tilde F_a(\tilde{\mathbf{z}})}{\tilde g^2(\tau_k) - a(\tau - \tau_k)/2} - \frac{\tilde F_\theta(\tilde{\mathbf{z}})}{\tilde g^2(\tau_k)}\bigg]^T(\mathbf{y} - \tilde{\mathbf{z}})\mathrm{d}\mathbf{y}\nonumber\\
    &\le 2\lim_{\tau \to \tau_k+} \bigg\|\frac{\tilde F_a(\tilde{\mathbf{z}})}{\tilde g^2(\tau_k) - a(\tau - \tau_k)/2} - \frac{\tilde F_\theta(\tilde{\mathbf{z}})}{\tilde g^2(\tau_k)}\bigg\| \big(\mathbb{E}_{\tilde {\mathbf{Y}}(\tau)\sim \tilde p_{\tau | \tau_k}(\cdot | \tilde{\mathbf{z}})} \big[\|\tilde{\mathbf{Y}}(\tau) - \tilde{\mathbf{z}}\|^2\big] \big)^{1/2}\nonumber\\
    &= 0.
\end{align*}
It follows that
\begin{align}
    \mathbb{E}_{\tilde{\mathbf{Y}}(\tau_k)\sim \tilde p_{\tau_k}}\bigg[\lim_{\tau \to \tau_k+}\int_{\mathbb{R}^d} \tilde p_{\tau | \tau_k}(\mathbf{y} | \tilde{\mathbf{Y}}(\tau_k)) \log\frac{\tilde p_{\tau | \tau_k}^a(\mathbf{y} | \tilde{\mathbf{Y}}(\tau_k))}{\tilde p^\theta_{\tau | \tau_k}(\mathbf{y} | \tilde{\mathbf{Y}}(\tau_k))}\mathrm{d}\mathbf{y}\bigg] \le 0.\label{eq: limit_KL_Gaussian}
\end{align}
Combining \eqref{eq: limit_KL_decomposion}, \eqref{eq: limit_KL_auxiliary} and \eqref{eq: limit_KL_Gaussian}, and using the non-negativity property of KL-divergence, we obtain
\begin{align*}
        \mathbb{E}_{\tilde{\mathbf{Y}}(\tau_k)\sim\tilde p_{\tau_k}} \bigg[\lim_{\tau \to \tau_k+}\text{KL}\big(\tilde p_{\tau | \tau_k}(\cdot | \tilde{\mathbf{Y}}(\tau_k)) || \tilde p^\theta_{\tau | \tau_k}(\cdot | \tilde{\mathbf{Y}}(\tau_k))\big)\bigg]= 0,

\end{align*}
which proves Lemma \ref{lemma: KL_dt}(a).



Next, we consider bounding $\frac{\mathrm{d}}{\mathrm{d}\tau}\text{KL}(\tilde p_{\tau | \tau_k}(\cdot | \tilde{\mathbf{z}})|| \tilde p^\theta_{\tau | \tau_k}(\cdot | \tilde{\mathbf{z}})$ for Lemma \ref{lemma: KL_dt}(b). For any given $\tilde{\mathbf{z}}\in\mathbb{R}^d$, we use the following notations for simplicity,
\begin{align*}
    \bar p_\tau:= \tilde p_{\tau | \tau_k}(\cdot | \tilde{\mathbf{z}}), \quad \bar p^\theta_\tau:= \tilde p^\theta_{\tau | \tau_k}(\cdot | \tilde{\mathbf{z}}).
\end{align*}

Using the same argument as in the proof of Lemma 6 in \cite{chen2023improved}, we have 
\begin{align}
    \frac{\mathrm{d}}{\mathrm{d}\tau}\text{KL}(\bar p_\tau || \bar p^\theta_\tau) = \int_{\mathbf{y}\in\mathbb{R}^d} \log \frac{\bar p_\tau}{\bar p_\tau^\theta}\cdot \frac{\partial \bar p_\tau}{\partial\tau}(\mathbf{y})\mathrm{d} \mathbf{y} - \int_{\mathbf{y}\in\mathbb{R}^d} \frac{\bar p_\tau}{\bar p_\tau^\theta}\cdot \frac{\partial \bar p^\theta_\tau}{\partial\tau}(\mathbf{y})\mathrm{d} \mathbf{y}. \label{eq: density_KL_dt}
\end{align}
Applying the Fokker-Planck equation to \eqref{eq: piece_reverse_SDE} and \eqref{eq: piece_reverse_SDE_simulation}, we get the evolutions of $\bar p_\tau$ and $\bar p^\theta_\tau$ as
\begin{align*}
    \frac{\partial \bar p_\tau}{\partial\tau}(\mathbf{y}) &= \nabla\cdot\bigg[-\tilde F(\mathbf{y}, \tau) \bar p_\tau(\mathbf{y}) + \frac{1}{2}\tilde g^2(\tau)\nabla \bar p_\tau(\mathbf{y})\bigg],\\
    \frac{\partial \bar p^\theta_\tau}{\partial\tau}(\mathbf{y}) &= \nabla\cdot\bigg[-\tilde F_\theta(\tilde{\mathbf{z}}) \bar p^\theta_\tau(\mathbf{y}) + \frac{1}{2}\tilde g^2(\tau_k)\nabla \bar p^\theta_\tau(\mathbf{y})\bigg].
\end{align*}

It again follows from the Fokker-Planck equation that the first term of \eqref{eq: density_KL_dt} can be expressed as
\begin{align*}
    \int_{\mathbf{y}\in\mathbb{R}^d} \log \frac{\bar p_\tau}{\bar p_\tau^\theta}\cdot \frac{\partial \bar p_\tau}{\partial\tau}(\mathbf{y})\mathrm{d} \mathbf{y} &= \int_{\mathbf{y}\in\mathbb{R}^d} \bar p_\tau(\mathbf{y}) [\tilde F(\mathbf{y}, \tau)]^T\nabla\log\frac{\bar p_\tau}{\bar p_\tau^\theta}(\mathbf{y})\mathrm{d} \mathbf{y}  - \frac{\tilde g^2(\tau)}{2}\int_{\mathbf{y}\in\mathbb{R}^d} [\nabla\bar p_\tau(\mathbf{y})]^T\nabla\log\frac{\bar p_\tau}{\bar p_\tau^\theta}(\mathbf{y}) \mathrm{d} \mathbf{y},
\end{align*}
and the second term of \eqref{eq: density_KL_dt}  as
\begin{align*}
    \int_{\mathbf{y}\in\mathbb{R}^d} \frac{\bar p_\tau}{\bar p_\tau^\theta}\cdot \frac{\partial \bar p^\theta_\tau}{\partial\tau}(\mathbf{y})\mathrm{d} \mathbf{y} = \int_{\mathbf{y}\in\mathbb{R}^d} \bar p^\theta_\tau(\mathbf{y}) [\tilde F_\theta(\tilde{\mathbf{z}})]^T \nabla\frac{\bar p_\tau}{\bar p_\tau^\theta}(\mathbf{y}) \mathrm{d} \mathbf{y} - \frac{\tilde g^2(\tau_k)}{2}\int_{\mathbf{y}\in\mathbb{R}^d} [\nabla\bar p^\theta_\tau(\mathbf{y})]^T\nabla\frac{\bar p_\tau}{\bar p_\tau^\theta}(\mathbf{y})\mathrm{d} \mathbf{y}.
\end{align*}


We compute
\begin{align}
    &\int_{\mathbf{y}\in\mathbb{R}^d} \bar p_\tau(\mathbf{y}) [\tilde F(\mathbf{y}, \tau)]^T\nabla\log\frac{\bar p_\tau}{\bar p_\tau^\theta}(\mathbf{y})\mathrm{d} \mathbf{y} - \int_{\mathbf{y}\in\mathbb{R}^d} \bar p^\theta_\tau(\mathbf{y}) \tilde F_\theta(\tilde{\mathbf{z}})^T\nabla\frac{\bar p_\tau}{\bar p_\tau^\theta}(\mathbf{y}) \mathrm{d} \mathbf{y} \nonumber\\
    &= \int_{\mathbf{y}\in\mathbb{R}^d} \bar p_\tau(\mathbf{y}) [\tilde F(\mathbf{y}, \tau)]^T\nabla\log\frac{\bar p_\tau}{\bar p_\tau^\theta}(\mathbf{y})\mathrm{d} \mathbf{y} - \int_{\mathbf{y}\in\mathbb{R}^d} \bar p_\tau(\mathbf{y}) \tilde F_\theta(\tilde{\mathbf{z}})^T\nabla\log\frac{\bar p_\tau}{\bar p_\tau^\theta}(\mathbf{y}) \mathrm{d} \mathbf{y}\nonumber\\
    &= \int_{\mathbf{y}\in\mathbb{R}^d} \bar p_\tau(\mathbf{y}) [\tilde F(\mathbf{y}, \tau) - \tilde F_\theta(\tilde{\mathbf{z}})]^T\nabla\log\frac{\bar p_\tau}{\bar p_\tau^\theta}(\mathbf{y})\mathrm{d} \mathbf{y} \nonumber\\
    &\le \int_{\mathbf{y}\in\mathbb{R}^d} \bar p_\tau(\mathbf{y}) \bigg[\frac{1}{C_{KL}}\big\|\tilde F(\mathbf{y}, \tau) - \tilde F_\theta(\tilde{\mathbf{z}})\big\|^2 + \frac{C_{\text{KL}}}{4}\bigg\|\nabla\log\frac{\bar p_\tau}{\bar p_\tau^\theta}(\mathbf{y})\bigg\|^2\bigg]\mathrm{d} \mathbf{y} \nonumber\\
    &= \frac{1}{C_{KL}}\mathbb{E}_{\bar{\mathbf{Y}}(\tau)\sim\bar p_\tau} \big[\big\|\tilde F(\bar{\mathbf{Y}}(\tau), \tau) - \tilde F_\theta(\tilde{\mathbf{z}})\big\|^2\big] + \frac{C_{\text{KL}}}{4}\mathbb{E}_{\bar{\mathbf{Y}}(\tau)\sim\bar p_\tau} \bigg[\bigg\|\nabla\log\frac{\bar p_\tau(\bar{\mathbf{Y}}(\tau))}{\bar p_\tau^\theta(\bar{\mathbf{Y}}(\tau))}\bigg\|^2\bigg], \label{eq: KL_dt_part1}
\end{align}
where the inequality is from the fact that $\mathbf{x}^T\mathbf{y} \le \frac{1}{C_{\text{KL}}}\|\mathbf{x}\|^2 + \frac{C_{\text{KL}}}{4}\|\mathbf{y}\|^2$ for any $\mathbf{x}, \mathbf{y}\in\mathbb{R}^d$ and any fixed constant $C_{\text{KL}} > 0$.


In addition, we have
\begin{align}
    &\frac{\tilde g^2(\tau_k)}{2}\int_{\mathbf{y}\in\mathbb{R}^d} [\nabla\bar p^\theta_\tau(\mathbf{y})]^T\nabla\frac{\bar p_\tau}{\bar p_\tau^\theta}(\mathbf{y})\mathrm{d} \mathbf{y} - \frac{\tilde g^2(\tau)}{2}\int_{\mathbf{y}\in\mathbb{R}^d} [\nabla\bar p_\tau(\mathbf{y})]^T\nabla\log\frac{\bar p_\tau}{\bar p_\tau^\theta}(\mathbf{y}) \mathrm{d} \mathbf{y} \nonumber\\
    &= \frac{\tilde g^2(\tau_k)}{2}\int_{\mathbf{y}\in\mathbb{R}^d} \bar p^\theta_\tau(\mathbf{y})[\nabla\log\bar p^\theta_\tau(\mathbf{y})]^T\nabla\frac{\bar p_\tau}{\bar p_\tau^\theta}(\mathbf{y})\mathrm{d} \mathbf{y}  - \frac{\tilde g^2(\tau)}{2}\int_{\mathbf{y}\in\mathbb{R}^d}\bar  p_\tau(\mathbf{y})[\nabla\log\bar p_\tau(\mathbf{y})]^T\nabla\log\frac{\bar p_\tau}{\bar p_\tau^\theta}(\mathbf{y}) \mathrm{d} \mathbf{y}\nonumber\\
    &= \frac{\tilde g^2(\tau_k)}{2}\int_{\mathbf{y}\in\mathbb{R}^d}\bar p_\tau(\mathbf{y})[\nabla\log\bar p^\theta_\tau(\mathbf{y})]^T\nabla\log\frac{\bar p_\tau}{\bar p_\tau^\theta}(\mathbf{y})\mathrm{d} \mathbf{y} - \frac{\tilde g^2(\tau)}{2}\int_{\mathbf{y}\in\mathbb{R}^d} \bar p_\tau(\mathbf{y})[\nabla\log\bar p_\tau(\mathbf{y})]^T\nabla\log\frac{\bar p_\tau}{\bar p_\tau^\theta}(\mathbf{y}) \mathrm{d} \mathbf{y}\nonumber\\
    &= -\frac{1}{2}\int_{\mathbf{y}\in\mathbb{R}^d} \bar p_\tau(\mathbf{y})[\tilde g^2(\tau)\nabla\log\bar p_\tau(\mathbf{y}) - \tilde g^2(\tau_k)\nabla\log\bar p^\theta_\tau(\mathbf{y})]^T \nabla\log\frac{\bar p_\tau}{\bar p_\tau^\theta}(\mathbf{y})\mathrm{d} \mathbf{y}\nonumber\\
    &= \frac{1}{2}\int_{\mathbf{y}\in\mathbb{R}^d} \bar p_\tau(\mathbf{y})[\tilde g^2(\tau_k) - \tilde g^2(\tau)][\nabla\log\bar p_\tau(\mathbf{y})]^T \nabla\log\frac{\bar p_\tau}{\bar p_\tau^\theta}(\mathbf{y})\mathrm{d} \mathbf{y}  - \frac{1}{2}\int_{\mathbf{y}\in\mathbb{R}^d} \bar p_\tau(\mathbf{y}) \tilde g^2(\tau_k)\bigg\|\nabla\log\frac{\bar p_\tau}{\bar p_\tau^\theta}(\mathbf{y})\bigg\|^2\mathrm{d} \mathbf{y}\nonumber\\
    &\le \frac{1}{4C_{\text{KL}}}\int_{\mathbf{y}\in\mathbb{R}^d} \bar p_\tau(\mathbf{y})[\tilde g^2(\tau_k) - \tilde g^2(\tau)]^2\big\|\nabla\log\bar p_\tau(\mathbf{y})\big\|^2\mathrm{d}\mathbf{y} \nonumber\\
    &\qquad + \bigg[\frac{C_{\text{KL}}}{4} - \frac{1}{2} \tilde g^2(\tau_k)\bigg] \int_{\mathbf{y}\in\mathbb{R}^d} \bar p_\tau(\mathbf{y}) \bigg\|\nabla\log\frac{\bar p_\tau}{\bar p_\tau^\theta}(\mathbf{y})\bigg\|^2\mathrm{d} \mathbf{y}\nonumber\\
    &= \frac{[\tilde g^2(\tau_k) - \tilde g^2(\tau)]^2}{4C_{\text{KL}}} \mathbb{E}_{\bar{\mathbf{Y}}(\tau) \sim \bar p_\tau} \big[\big\|\nabla\log\bar p_\tau(\bar{\mathbf{Y}}(\tau))\big\|^2\big] \nonumber\\
    &\qquad + \frac{1}{2}\bigg[\frac{C_{\text{KL}}}{2}- \tilde g^2(\tau_k)\bigg] \mathbb{E}_{\bar{\mathbf{Y}}(\tau) \sim \bar p_\tau}\bigg\|\nabla\log\frac{\bar p_\tau(\bar{\mathbf{Y}}(\tau))}{\bar p_\tau^\theta(\bar{\mathbf{Y}}(\tau))}\bigg\|^2, \label{eq: KL_dt_part2}
\end{align}
where the inequality is due to $\mathbf{x}^T\mathbf{y} \le \frac{1}{2C_{\text{KL}}}\|\mathbf{x}\|^2 + \frac{C_{\text{KL}}}{2}\|\mathbf{y}\|^2$ for any $\mathbf{x}, \mathbf{y}\in\mathbb{R}^d$ and any fixed constant $C_{\text{KL}} > 0$.

Finally, by combining \eqref{eq: KL_dt_part1} and \eqref{eq: KL_dt_part2}, we can infer from \eqref{eq: density_KL_dt} that \eqref{eq: density_KL_dt_bound} holds. This completes the proof of Lemma~\ref{lemma: KL_dt}.

