\end{align*}

\begin{align}\label{eq: posterior_cov_trace_dt}
    \mathbb{E}_{\mathbf{Y}(\tau)}\big[\text{trace}(\boldsymbol{\Sigma}_\tau^2)\big] = -\frac{\mathrm{d} \tau(s)}{\mathrm{d} s}\frac{\mathrm{d}}{\mathrm{d} \tau}\mathbb{E}_{\mathbf{Y}(\tau)}\big[\text{trace}(\boldsymbol{\Sigma}_{\tau})\big] = \frac{\sigma_\tau^3}{2\dot\sigma_\tau}\frac{\mathrm{d}}{\mathrm{d} \tau}\mathbb{E}_{\mathbf{Y}(\tau)}\big[\text{trace}(\boldsymbol{\Sigma}_{\tau})\big],
\end{align}

\begin{align*}
    \nabla^2\log q_\tau(\mathbf{y}_\tau|\mathbf{c}) = -\sigma_\tau^{-2}I_d + \sigma_\tau^{-4}{\text{Cov}}_{q_{0|\tau}(\cdot | \mathbf{y}(\tau), \mathbf{c})}\big(\mathbf{y}(\tau) - \lambda_\tau\mathbf{Y}(0)\big) = -\sigma_\tau^{-2}I_d + \sigma_\tau^{-4}\lambda_\tau^2\boldsymbol{\Sigma}_\tau.
\end{align*}

Letting $\Lambda(\tau) = \exp\big(\int_{0}^\tau f(s)\mathrm{d} s\big)$ and applying It\^{o}'s formula to the forward SDE \eqref{eq: forward_SDE_DDPM} under the condition $\mathbf{c}$, we have
\begin{align*}
    \mathrm{d} [\Lambda(\tau)\mathbf{Y}(\tau)] = f(\tau)\Lambda(\tau)\mathbf{Y}(\tau)\mathrm{d}\tau + \Lambda(\tau)\big[-f(\tau)\mathbf{Y}(\tau)\mathrm{d}\tau + g(\tau)\mathrm{d} \mathbf{B}(\tau)\big] = \Lambda(\tau)g(\tau)\mathrm{d} \mathbf{B}(\tau).
\end{align*}
By the Dambis-Dubins–Schwarz theorem {\citep[Theorem 3.4.6]{karatzas2014brownian}}, there is a process $(\hat{\mathbf{B}}(s))_{s\ge 0}$ such that under the time change
\begin{align*}
    \kappa(s) := \inf\bigg\{\tau: \int_{0}^\tau\Lambda^2(u)g^2(u)\mathrm{d} u > s\bigg\} = \inf\bigg\{\tau: \exp\big(a\tau^2/2 + b\tau\big) - 1> s\bigg\},
\end{align*}
we have
\begin{align*}
    \hat{\mathbf{B}}(e^{a\tau^2/2 + b\tau} - 1) = \int_{0}^\tau\Lambda(u)g(u)\mathrm{d} \mathbf{B}(u),
\end{align*}
where $(\hat{\mathbf{B}}(s))_{s\ge 0}$ is a standard Brownian motion w.r.t. the filtration $\big(\mathcal{F}_{\kappa(s)}\big)_{s\ge0}$, while $(\mathcal{F}_\tau)_{\tau \ge 0}$ is the natural filtration generated by $(\mathbf{B}(\tau))_{\tau \ge 0}$. Then, for any $s > 0$, we have
\begin{align*}
    \Lambda(\kappa(s))\mathbf{Y}(\kappa(s)) = \mathbf{Y}(0) + \int_{0}^{\kappa(s)}\Lambda(u)g(u)\mathrm{d} \mathbf{B}(u) = \mathbf{Y}(0) + \hat{\mathbf{B}}(s).
\end{align*}
Now, if we set $\mathbf{U}(0) = 0$ and
\begin{align*}
    \mathbf{U}(s) := s\Lambda(\kappa(s^{-1}))\mathbf{Y}(\kappa(s^{-1})) = s\mathbf{Y}(0) + s\hat{\mathbf{B}}(s^{-1}),\ \text{for } s > 0,
\end{align*}
then we find that $\mathbf{U}$ satisfies the definition of the stochastic localization in \eqref{eq: stochastic_localization}, because $\mathbf{Y}(0)\sim p_{\text{target}}(\cdot | \mathbf{c})$ and the law of $\big(s\hat{\mathbf{B}}(s^{-1})\big)_{s\ge 0}$ is the same as the law of $\big(\hat{\mathbf{B}}(s)\big)_{s\ge 0}$. The proof is complete by noting that $\kappa(s^{-1}) = \tau(s)$ in \eqref{eq: diffusion_localization_time_change} and $\Lambda(\tau) = \lambda_\tau^{-1}$ in \eqref{eq: forward_SDE_coeff}.

\begin{align*}
    \mathrm{d} [\Lambda(\tau)\mathbf{Y}(\tau)] = f(\tau)\Lambda(\tau)\mathbf{Y}(\tau)\mathrm{d}\tau + \Lambda(\tau)\big[-f(\tau)\mathbf{Y}(\tau)\mathrm{d}\tau + g(\tau)\mathrm{d} \mathbf{B}(\tau)\big] = \Lambda(\tau)g(\tau)\mathrm{d} \mathbf{B}(\tau).
\end{align*}

\begin{align*}
    \kappa(s) := \inf\bigg\{\tau: \int_{0}^\tau\Lambda^2(u)g^2(u)\mathrm{d} u > s\bigg\} = \inf\bigg\{\tau: \exp\big(a\tau^2/2 + b\tau\big) - 1> s\bigg\},
\end{align*}

\begin{align*}
    \hat{\mathbf{B}}(e^{a\tau^2/2 + b\tau} - 1) = \int_{0}^\tau\Lambda(u)g(u)\mathrm{d} \mathbf{B}(u),
\end{align*}

\begin{align*}
    \Lambda(\kappa(s))\mathbf{Y}(\kappa(s)) = \mathbf{Y}(0) + \int_{0}^{\kappa(s)}\Lambda(u)g(u)\mathrm{d} \mathbf{B}(u) = \mathbf{Y}(0) + \hat{\mathbf{B}}(s).
\end{align*}

\begin{align*}
    \mathbf{U}(s) := s\Lambda(\kappa(s^{-1}))\mathbf{Y}(\kappa(s^{-1})) = s\mathbf{Y}(0) + s\hat{\mathbf{B}}(s^{-1}),\ \text{for } s > 0,
\end{align*}

\caption{Offline q-Learning Mean–Variance Algorithm with Synthetic Wealth Simulator}
\textbf{Inputs}: initial state $x(0)$, horizon $T$, time step $\Delta t$, number of steps $N_T = T/\Delta t$, number of episodes $M$, number of real asset price paths $H$, number of synthetic paths (generated at each episode) $H_s$, parameterized value function $J_{\varphi}(\cdot,\cdot; w)$ and policy $\pi_{\psi}(\cdot,\cdot; w)$, initial Lagrange multiplier $w$, learning rate functions $\alpha_{\varphi}(\cdot),\alpha_{\psi}(\cdot), \alpha_w(\cdot)$

\textbf{Required program}: a real wealth simulator $x' = Wealth_{\Delta t}(t,x,a)$ that takes current time--state pair $(t,x)$ and action $a$ as inputs and generates state $x'$ at time $t + \Delta t$ according to \eqref{eq: MV_wealth_process}, a synthetic wealth simulator $x'=Wealth_{\Delta t}(t, x, a; G(\theta))$ based on synthetic paths from a generative model $G(\theta)$, q-function $q_{\psi}(t, x, a; w) = \log\pi_\psi(t, x, a; w)$.


\textbf{Learning procedure}:
\begin{algorithmic}
\FOR{episode $m = 1$ \TO $M$}
\STATE Generate $H_s$ synthetic asset price paths by $G(\theta)$.
\STATE Initialize $n = 0$ and store $x^{(j)}(t_n) \leftarrow  x(0)$ for $j=1,..., H + H_s$.

\WHILE{$n < N_T$}
\FOR{path $j=1$ \TO $H + H_s$}
    \STATE{Generate action $a^{(j)}(t_n)\sim \pi_{\psi}(\cdot|t_n, x^{(j)}(t_n); w)$.

    Compute and store the test functions
    \vspace{-3mm}
    \[
        \xi^{(j)}(t_n)= \frac{\partial J_\varphi}{\partial \varphi}(t_{n},x^{(j)}(t_n); w),\quad \zeta^{(j)}(t_n) = \frac{\partial q_{\psi}}{\partial \psi}(t_{n}, x^{(j)}(t_n), a^{(j)}(t_n); w).
    \]
    \vspace{-5mm}
    \IF{$j \le H$}
        \STATE In the real wealth simulator: $x^{(j)}(t_{n + 1}) = Wealth_{\Delta t}(t_n, x^{(j)}(t_n), a^{(j)}(t_n)).$
    \ELSE
        \STATE In the synthetic wealth simulator: $x^{(j)}(t_{n + 1}) = Wealth_{\Delta t}(t_n, x^{(j)}(t_n), a^{(j)}(t_n); G(\theta)).$
    \ENDIF

    }

\ENDFOR
\STATE Update $n \leftarrow n + 1$.

\ENDWHILE	

\STATE Store the terminal wealth $x^{(j)}(T; m) \leftarrow x^{(j)}(t_{N_T})$ for $j=1,..., H + H_s$.

\STATE For path $j=1, \cdots H + H_s$, compute
\vspace{-3mm}
\begin{align*}
    \Delta \varphi^{(j)} = \sum_{n=0}^{N_T - 1} \xi^{(j)}(t_n) \big[
    J_\varphi(t_{n + 1}, x^{(j)}(t_{n + 1}); w) - J_\varphi(t_n, x^{(j)}(t_n); w) -q_{\psi}(t_n, x^{(j)}(t_n) ,a^{(j)}(t_n); w)\Delta t \big],\\
    \Delta \psi^{(j)} = \sum_{n=0}^{N_T - 1} \zeta^{(j)}(t_n)\big[
    J_\varphi(t_{n + 1}, x^{(j)}(t_{n + 1}); w) - J_\varphi(t_n, x^{(j)}(t_n); w) - q_{\psi}(t_n, x^{(j)}(t_n), a^{(j)}(t_n); w)\Delta t \big] .
\end{align*}

\vspace{-3mm}
\STATE Update $\varphi$ and $\psi$: $\varphi \leftarrow \varphi + \frac{\alpha_{\varphi}(m)}{H + H_s}\sum_{j=1}^{H + H_s}\Delta \varphi^{(j)},\ \psi \leftarrow \psi + \cdot\frac{\alpha_{\psi}(m)}{H + H_s} \sum_{j=1}^{H + H_s}\Delta \psi ^{(j)}$

\vspace{1mm}
\STATE Update $w$ (Lagrange multiplier) every $L$ episodes:
\IF{$m\equiv 0$ mod $L$}
    \STATE{$w\leftarrow w - \alpha_w \frac{1}{L}\sum_{i=m - L + 1}^m \frac{1}{H + H_s}\sum_{j=1}^{H + H_s}x^{(j)}(T; i)$}
\ENDIF

\ENDFOR
\end{algorithmic}
\label{alg: qL_mv}

\begin{align*}
    \Delta \varphi^{(j)} = \sum_{n=0}^{N_T - 1} \xi^{(j)}(t_n) \big[
    J_\varphi(t_{n + 1}, x^{(j)}(t_{n + 1}); w) - J_\varphi(t_n, x^{(j)}(t_n); w) -q_{\psi}(t_n, x^{(j)}(t_n) ,a^{(j)}(t_n); w)\Delta t \big],\\
    \Delta \psi^{(j)} = \sum_{n=0}^{N_T - 1} \zeta^{(j)}(t_n)\big[
    J_\varphi(t_{n + 1}, x^{(j)}(t_{n + 1}); w) - J_\varphi(t_n, x^{(j)}(t_n); w) - q_{\psi}(t_n, x^{(j)}(t_n), a^{(j)}(t_n); w)\Delta t \big] .
\end{align*}

\begin{align*}
    L(\mathbf{z}, \tau_k) = \boldsymbol{\gamma}(k) \odot (\mathbf{W}\mathbf{z} + \mathbf{b}),
\end{align*}

\begin{align*}
    s_\theta(\tau_k, \mathbf{x}, \mathbf{c}) = A_m\circ L_m(\cdot, \tau_k)\circ A_{m - 1}\circ L_{m - 1}(\cdot, \tau_k)\circ \cdots \circ A_1\circ L_1((\mathbf{x}, \mathbf{c}), \tau_k).
\end{align*}


